COLLDATA("sh21494","ur",[[201,"اسی سند کے ساتھ مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اونٹنی کے پیٹ میں موجود بچے کو کھا سکتے ہو۔“","",{"t":"اونٹنی کے پیٹ میں موجود بچے کا حکم","k":"إسنادہ کسابقہ: سنن الدارقطنی: ۲۷۳/۴، ح: ۴۶۸۹۔ مسند الامام احمد کی حدیث (۱۱۳۴۳، ۳۹/۳، عن ابی سعید، وسندہ حسن) اس سے بے نیاز کر دیتی ہے۔"}],[202,"سیدنا عبد اللہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان طعن و تشنیع کرنے نہیں ہوتا اور نہ لعنت کرنے والا اور نہ فحش گو اور نہ بد زبان ہوتا ہے۔“","",{"t":"اسلام کے منافی افعال","k":"حسن: سنن الترمذی، ح: ۱۹۷۷۔ الادب المفرد، ح: ۳۱۲۔ المعجم الكبير، ح: ۱۰۴۸۳۔ مسند ابی یعلی، ح: ۵۳۷۹۔ مسند احمد: ۴۰۴/۱۔ الصحیحۃ، ح: ۳۲۰","f":"ایک سچے مسلمان کے شایان شان نہیں کہ وہ طعن و تشنیع کرنے والا، لعنت کرنے والا، فحش گو اور بد زبان ہو۔"}],[203,"سیدنا انس رضی اللہ عنہ کہتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ کسی چیز کی طرف جھکے گویا آپ مصافحہ کر رہے ہوں، اس وقت آپ طواف میں تھے۔ ہم نے عرض کی: اے اللہ کے رسول! ہم نے آپ کو دیکھا کہ آپ کسی چیز کی طرف جھکے ہیں جیسے اس سے مصافحہ کر رہے ہوں لیکن ہم نے کوئی چیز نہیں دیکھی؟ آپ نے فرمایا: “وہ عیسی ابن مریم علیہ السلام تھے، میں نے ان کا انتظار کیا یہاں تک کہ انہوں نے اپنا طواف پورا کیا اور میں نے انہیں سلام کہا۔”","",{"t":"نبی صلی اللہ علیہ وسلم کا سیدنا عیسیٰ علیہ السلام سے مصافحہ کرنا","k":"إسناده ضعیف جدا: تاریخ دمشق: ۴۸۶/۴۷۔ اسماعیل بن ابان، جابر جعفی اور ابو عقال متروک ہیں۔"}],[204,"سیدنا ابو سعید خدری رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے ﴿فِیْهَا أَزْوَاجٌ مُّطَهَّرَةٌ﴾ (اس میں نہایت پاک بیویاں ہیں) کی تفسیر روایت کرتے ہیں کہ آپ نے فرمایا: “(وہ) حیض، پیشاب، پاخانہ، رینٹ اور تھوک سے (پاک ہیں)۔”","",{"t":"﴿فِیْهَا أَزْوَاجٌ مُّطَهَّرَةٌ﴾ [البقرة: ۲۵] کی تفسیر","k":"منکر: صفة الجنة لابی نعیم، ح: ۳۶۳۔ امام ذہبی فرماتے ہیں کہ اس حدیث کا مرفوع ہونا خطا ہے۔ دیکھیے: میزان الاعتدال: (۶۰۹/۲)۔ ابن حبان کہتے ہیں کہ یہ قتادہ کا قول ہے جسے اس (عبدالرزاق بن عمر) نے مرفوع بیان کر دیا۔ نبی صلی اللہ علیہ وسلم کا ایسا کوئی فرمان نہیں۔ (المجروحین: ۱۴۶/۲)۔ امام ابن کثیر بھی اسے قتادہ کا قول بناتے ہیں۔ (تفسیر القرآن: ۹۱/۱)۔"}],[205,"اسے سیدنا ابو سعید رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے اسی کی مثل روایت کیا ہے۔","",{"k":"ایضا۔"}],[206,"صالح بن مسمار اور جعفر بن برقان سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے حارث بن مالک سے فرمایا: “اے حارث بن مالک! تم کون ہو؟” انہوں نے کہا: اے اللہ کے رسول! (میں) مومن ہوں۔ آپ نے فرمایا: “سچے مومن ہو؟” انہوں نے کہا: سچا مومن ہوں۔ آپ نے فرمایا: “ہر حق کی ایک حقیقت ہوتی ہے، تو اس کی کیا حقیقت ہے؟” انہوں نے کہا: میں نے اپنا نفس دنیا سے پھیر لیا ہے، اپنی رات کو بیدار رکھا ہے اور اپنے دن کو پیاسا کر لیا ہے (یعنی رات کو قیام اور دن کو روزہ رکھتا ہوں) اور (اب) گویا میں اپنے رب کے عرش کی طرف دیکھ رہا ہوں اور گویا اہل جنت کی طرف دیکھ رہا ہوں، وہ اس میں ایک دوسرے کی زیارت کر رہے ہیں اور گویا اہل جہنم کا چیخنا چلانا سن رہا ہوں۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا: “یہ ایسا مومن ہے کہ اللہ تعالیٰ نے اس کے دل کو منور کر دیا ہے۔”","",{"t":"سچا مومن","k":"إسناده ضعیف: المصنف لعبد الرزاق، ح: ۲۰۱۱۴۔ شعب الایمان، ح: ۱۰۱۰۸۔ الزهد لابن المبارک، ح: ۳۱۴۔ صالح بن مسمار اور جعفر بن برقان صحابی نہیں، ان کے اور رسول اللہ صلی اللہ علیہ وسلم کے درمیان انقطاع ہے، اس کے دیگر طرق بھی ضعیف ہیں۔"}],[207,"سیدنا ابن عمر رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہر چھوٹے اور بڑے، آزاد اور غلام کی طرف سے ایک صاع جو یا ایک صاع کھجور صدقہ فطر ادا کرنے کا حکم فرمایا۔ پھر لوگوں نے بعد میں اس (صاع) کو گیہوں کے دو مد (نصف صاع) کے برابر ٹھہرا لیا۔","",{"t":"صدقہ فطر","k":"صحیح البخاری، ح: ۱۵۰۳۔ صحیح مسلم، ح: ۹۸۴۔ سنن أبي داؤد، ح: ۱۶۱۳۔ سنن الترمذی، ح: ۶۷۵۔ سنن النسائی، ح: ۲۵۰۲۔ سنن ابن ماجه، ح: ۱۸۲۵۔ صحیح ابن خزیمة، ح: ۲۳۹۳۔","f":"صدقۃ الفطر کا رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا، لہذا یہ فرض ہے، بیشتر احادیث میں بھی اس کے لیے “فَرَضَ” کے الفاظ آئے ہیں۔ امام ابن المنذر فرماتے ہیں کہ اس کی فرضیت پر اجماع ہے۔ (کتاب الاجماع: ۳۵)۔\nصدقہ فطر جنس خوراک میں سے ایک صاع ادا کیا جائے گا جو کہ محتاط اندازے کے مطابق اڑھائی کلو ہے۔\nگیہوں کے دو مد (نصف صاع) صدقہ فطر میں ادا کرنا بعض اہل علم کا ذاتی اجتہاد تھا، اس پر کوئی صحیح دلیل نہیں تھی، اسی لیے صحابہ کرام نے اس سے اتفاق نہیں کیا۔ دیکھیے: سنن أبي داؤد، (ح: ۱۶۱۶ و سنده صحیح)۔\nافضل یہی ہے کہ صدقہ فطر جنس خوراک سے ادا کیا جائے کیونکہ احادیث میں مختلف اجناس ہی کی تعیین فرمائی گئی ہے تاہم اگر خوراک کے بدلے میں اس کی قیمت ادا کر دی جائے تو یہ بھی جائز ہے۔ کیونکہ صدقہ فطر کا مقصد مساکین کو کھانا دینا ہے اور یہ چیز قیمت سے بھی ممکن ہے۔\nصدقہ فطر نماز عید کی ادائیگی کے لیے گھر سے نکلنے سے پہلے پہلے ادا کر دینا چاہیے۔"}],[208,"سیدنا سعد بن ابی وقاص رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ مال تقسیم کیا تو آپ نے کچھ لوگوں کو عطا کیا اور دوسروں کو نہ دیا۔ میں (سعد) نے عرض کیا: اے اللہ کے رسول! آپ نے فلاں اور فلاں کو عطا کیا اور فلاں کو عطا نہیں کیا حالانکہ وہ بھی مومن ہے۔ آپ نے فرمایا: “مومن ہرگز نہ کہو، لیکن مسلم کہو۔”","",{"t":"تالیف قلب","k":"صحیح البخاری، ح: ۱۴۷۸۔ صحیح مسلم، ح: ۱۵۰۔ سنن أبي داؤد، ح: ۴۶۸۳۔ سنن النسائی، ح: ۴۹۹۵۔","f":"ایمان کا تعلق اگر چہ ظاہر و باطن سے ہے مگر اسلام کا تعلق ظاہری امور سے ہے، اس لیے کسی شخص کے ظاہر کو دیکھ کر اسے مسلمان تو کہہ سکتے مگر صاحب ایمان کہنا درست نہیں۔ کیونکہ باطن کے امور اللہ کے سوا کوئی نہیں جانتا۔ اس لیے آپ نے فرمایا کہ کسی کو مومن نہ کہو بلکہ مسلم کہو۔\nآپ نے تالیف قلب کے لیے کچھ لوگوں کو مال دیا۔ اس میں حکمت یہ تھی کہ نہ دینے کی وجہ سے کہیں وہ مرتد نہ ہو جائیں اور جن کو آپ نے نہیں دیا ان کے متعلق ایسا خدشہ نہ تھا۔\nحاکم کے لیے جائز ہے کہ وہ سرکاری مال میں حالات کے پیش نظر اپنی صوابدید کے مطابق تصرف کرے۔\nمستحق شخص کو حق دلانے کے لیے سفارش کرنا جائز ہے۔"}],[209,"سیدنا ابن عمر رضی اللہ عنہما سے مروی ہے کہ وہ ولد الزنا کو آزاد کر دیا کرتے تھے اور نصرانی کو آزاد نہیں کیا کرتے تھے۔","",{"t":"ولد الزنا اور نصرانی کو آزاد کرنا","k":"إسناده ضعیف: محمد بن یزید کا تعیین مشکل ہے۔ الموطا لامام مالک کی حدیث (۱۵۱۸ و سنده صحیح) اس سے بے نیاز کر دیتی ہے۔"}],[210,"ابن شہاب سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے گرم گرم کھانا کھانے سے منع فرمایا ہے۔","",{"t":"گرم کھانا کھانے کی ممانعت","k":"إسناده ضعیف: ابن شہاب اور رسول اللہ صلی اللہ علیہ وسلم کے درمیان انقطاع ہے۔ اس کے دیگر طرق و شواہد بھی ضعیف ہیں۔ سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں کہ کوئی کھانا اس وقت تک نہ کھایا جائے جب تک اس کا دھواں نہ چلا جائے۔ (السنن الكبری للبیهقی، ح: ۱۴۶۳۱ و سنده صحیح)۔"}],[211,"سیدنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “بہترین کھانا وہ ہے جو ٹھنڈا اور میٹھا ہو اور بہترین مشروب بھی وہی ہے جو ٹھنڈا اور میٹھا ہو۔”","",{"t":"بہترین کھانا اور بہترین مشروب","k":"إسناده ضعیف: طلحہ بن عمرو متروک اور یحیی بن ابی سلیمان ضعیف ہے۔"}],[212,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کلام کرتے تو مختصر کلام کرتے اور تم لوگ کلام کو بہت پھیلاتے ہو۔","",{"t":"آپ صلی اللہ علیہ وسلم کا انداز گفتگو","k":"إسناده ضعیف: مسند اسحاق بن راهویة، ح: ۱۶۸۵۔ یزید بن ابی حبیب اور سیدہ عائشہ رضی اللہ عنہا کے درمیان انقطاع ہے۔ صحیح البخاری کی حدیث (۳۵۶۸) اس سے بے نیاز کر دیتی ہے۔"}],[213,"امام زہری فرماتے ہیں: آپ صلی اللہ علیہ وسلم سے دریافت کیا گیا کہ کون سا مشروب زیادہ عمدہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “ٹھنڈا میٹھا۔”","",{"t":"عمدہ ترین مشروب","k":"إسناده ضعیف: سنن الترمذی، ح: ۱۸۹۶۔ المصنف لعبد الرزاق، ح: ۱۹۵۸۳۔ شعب الایمان، ح: ۵۵۲۷۔ زہری اور رسول اللہ صلی اللہ علیہ وسلم کے درمیان انقطاع ہے۔"}],[214,"سیدنا ابن عمر رضی اللہ عنہما فرماتے ہیں: ہم کھڑے ہو کر پی لیا کرتے تھے اور چلتے چلتے کھا لیا کرتے تھے۔","",{"t":"کھڑے ہو کر کھانا پینا","k":"صحیح: سنن الترمذی، ح: ۱۸۸۱۔ سنن ابن ماجه، ح: ۳۳۰۱۔ مسند احمد: ۱۰۸/۲۔ المنتقی لابن الجارود، ح: ۸۶۷۔ صحیح ابن حبان، ح: ۵۲۴۳۔ موارد الظمآن الی زوائد ابن حبان، ح: ۱۳۶۹۔","f":"یہ عہد رسالت کی بات ہے جو سیدنا ابن عمر رضی اللہ عنہما نے بیان فرمائی ہے۔ اس سے پتا چلا کہ کھڑے ہو کر اور چلتے پھرتے کھانا پینا جائز ہے۔ تاہم افضل یہ ہے کہ بیٹھ کر کھایا پیا جائے۔ امام نووی فرماتے ہیں: باب بیان جواز الشرب قائما و بیان ان الاکمل والافضل الشرب قاعدا۔ (ریاض الصالحین: ۶۳۳/۱)۔\nبعض مواقع پر نبی صلی اللہ علیہ وسلم نے بھی کھڑے ہو کر پانی پیا ہے۔ مثلاً دیکھیے: صحیح البخاری، ح: ۱۶۳۷۔ سنن الترمذی، ح: ۱۸۸۳۔ لہذا جن روایتوں میں کھڑے ہو کر پینے کی نہی وارد ہوئی ہے انہیں کراہت پر محمول کیا جائے گا۔ دیکھیے: شرح النووی على صحیح مسلم: (۱۹۹/۱۳)۔"}],[215,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “لوگوں میں سب سے بڑا جھوٹا وہ آدمی ہے کہ کسی نے کسی آدمی کی ہجو کی تو اس نے جواب میں پورے قبیلے کی ہجو کر دی، اور وہ آدمی ہے جو اپنے باپ کا انکار کرے اور اپنی ماں کو زانیہ قرار دے۔”","",{"t":"سب سے بڑا مجرم","k":"إسناده ضعیف: سنن ابن ماجه، ح: ۳۷۶۱۔ الادب المفرد، ح: ۸۷۴۔ السنن الكبری للبیهقی، ح: ۲۱۱۲۹۔ اعمش مدلس کا عنعنہ ہے۔ صحیح البخاری کی حدیث (ح: ۳۵۰۹) اس سے بے نیاز کر دیتی ہے۔"}],[216,"سیدنا ابو سعید اور ابو ہریرہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جو شخص رات کو اٹھا اور اپنی بیوی کو جگایا پھر دونوں نے مل کر دو رکعتیں پڑھیں تو اس رات وہ (اللہ کو) کثرت سے یاد کرنے والے مردوں اور عورتوں میں لکھے جاتے ہیں۔”","",{"t":"رات کو دو رکعت نماز پڑھنا","k":"إسناده ضعیف: سنن أبي داؤد، ح: ۱۴۵۱۔ سنن ابن ماجه، ح: ۱۳۳۵۔ صحیح ابن حبان، ح: ۲۵۶۹۔ شعب الایمان، ح: ۲۸۱۹۔ السنن الكبری للنسائی، ح: ۱۳۱۲۔ اعمش مدلس کا عنعنہ ہے۔ سنن ابی داؤد کی حدیث (۱۳۵۰: عن ابی ہریرہ، وسنده حسن) اس سے بے نیاز کر دیتی ہے۔"}],[217,"سیدنا عبد اللہ رضی اللہ عنہ فرماتے ہیں: جسے یہ بات پسند ہو کہ کل وہ اسلام کی حالت میں اللہ تعالیٰ سے ملاقات کرے تو اسے چاہیے کہ ان پانچ نمازوں کی حفاظت کرے جہاں سے ان کے لیے اذان دی جاتی ہے۔ کیونکہ اللہ عز وجل نے اپنے نبی صلی اللہ علیہ وسلم کے لیے ہدایت کے طریقے جاری فرمائے اور بلاشبہ یہ (نمازیں مسجد میں ادا کرنا) بھی ہدایت کے طریقوں میں سے ہے ... اور لمبی حدیث بیان فرمائی۔","",{"t":"نماز با جماعت کی فضیلت","k":"صحیح: دیکھیے: حدیث نمبر ۷۹۔"}],[218,"سیدنا محیصہ رضی اللہ عنہ سے مروی ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سینگی لگانے والے کی کمائی کے متعلق دریافت کیا تو آپ نے ان کو منع کر دیا پھر انہوں نے (دوبارہ) آپ سے ذکر کیا تو آپ نے فرمایا: “اسے اپنی اونٹنی کو کھلا دے۔”","",{"t":"سینگی لگانے والے کی کمائی","k":"صحیح: سنن أبي داؤد، ح: ۳۴۲۲۔ سنن الترمذی، ح: ۱۲۷۷۔ سنن ابن ماجه، ح: ۲۱۶۶۔ مسند احمد: ۴۳۶/۵۔ صحیح ابن حبان، ح: ۵۱۵۴۔ مسند الحمیدی، ح: ۸۷۸۔ الصحیحة، ح: ۴۰۰۰۔","f":"سینگی کو حجامہ اور پچھنے لگانا بھی کہتے ہیں۔ یہ قدیم طریقہ علاج ہے جس میں خاص طریقہ سے جسم سے خون نکالا جاتا ہے۔ یہ عمل جائز بلکہ سنت ہے۔\nسیدنا ابن عباس رضی اللہ عنہما فرماتے ہیں کہ ایک دفعہ نبی صلی اللہ علیہ وسلم نے سینگی لگوائی اور لگانے والے کو آپ نے اجرت دی اگر یہ (مزدوری) حرام ہوتی تو آپ اسے نہ دیتے۔ (صحیح البخاری، ح: ۲۱۰۳)۔ اس حدیث سے معلوم ہوا کہ سینگی لگانے کی اجرت حرام نہیں ہے۔ لہذا جن روایتوں میں اس اجرت کو خبیث وغیرہ کہا گیا ہے وہ کراہت پر محمول ہیں یا منسوخ ہیں۔ واللہ اعلم!"}],[219,"سیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “رضاعت طبیعت کو بدل دیتی ہے۔”","",{"t":"رضاعت طبیعت کو بدل دیتی ہے","k":"منکر: مسند الشهاب، ح: ۳۵۔ شیخ البانی نے اسے متعدد علل کی بناء پر سخت منکر قرار دیا ہے۔ دیکھیے: الضعیفة، (ح: ۱۵۶۱)۔"}],[220,"سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے تین گھڑیوں میں نماز پڑھنے سے منع فرمایا ہے: جس وقت سورج طلوع ہو رہا ہو۔ اور نصف النہار کے وقت، اور جس وقت وہ (سورج) غروب ہو رہا ہے۔","",{"t":"نماز کے ممنوع اوقات","k":"صحیح: المعجم الاوسط، ح: ۴۶۵۰۔ مسند البزار، ح: ۹۸۹۴۔ الفوائد المعللة لابی زرعة، ح: ۸۴۔","f":"احادیث میں پانچ اوقات میں نماز پڑھنے کی ممانعت آئی ہے: (۱) جس وقت سورج طلوع ہو رہا ہو۔ (۲) نصف النہار کے وقت (۳) جب سورج غروب ہو رہا ہو۔ (دیکھیے: مذکورہ بالا حدیث) (۴) نماز فجر کے بعد یہاں تک کہ سورج طلوع ہو جائے۔ (۵) اور عصر کے بعد۔ (دیکھیے: صحیح البخاری، ح: ۵۸۶)۔\nنبی صلی اللہ علیہ وسلم نے فرمایا: “صبح کی نماز پڑھو پھر نماز سے رک جاؤ حتی کہ سورج نکل کر بلند ہو جائے کیونکہ جب وہ طلوع ہوتا ہے تو شیطان کے دو سینگوں کے درمیان طلوع ہوتا ہے اور اس وقت کافر اس کو سجدہ کرتے ہیں اس کے بعد نماز پڑھو کیونکہ نماز کا مشاہدہ ہوتا ہے اس میں فرشتے حاضر ہوتے ہیں یہاں تک کہ جب نیزے کا سایہ اس کے ساتھ لگ جائے تو پھر نماز سے رک جاؤ (نصف النہار کے وقت) کیونکہ اس وقت جہنم بھڑکائی جاتی ہے پھر جب سایہ آگے آ جائے تو نماز پڑھو کیونکہ نماز کا مشاہدہ کیا جاتا ہے اور اس میں حاضری دی جاتی ہے۔ حتی کہ تم عصر سے فارغ ہو جاؤ پھر نماز سے رک جاؤ یہاں تک کہ سورج غروب ہو جائے کیونکہ وہ شیطان کے دو سینگوں میں غروب ہوتا ہے اور اس وقت کافر اس کے سامنے سجدہ ریز ہوتے ہیں۔ (صحیح مسلم، ح: ۸۳۲)۔”\nجس کی فرض نماز رہ جائے اور اسے یاد آ جائے یا وہ نیند سے بیدار ہوا ہو تو وہ ممنوع اوقات میں بھی نماز پڑھ سکتا ہے۔ (دیکھیے: صحیح البخاری، ح: ۵۹۷)۔\nسنن اگر رہ گئی ہوں تو وہ بھی پڑھی جا سکتی ہیں۔ دیکھیے: صحیح ابن خزیمة، (ح: ۱۱۱۶)۔ سنن أبي داؤد، (ح: ۱۲۶۷)۔ سنن الترمذی، (ح: ۴۲۲)۔ نیز دیکھیے: صحیح البخاری، (ح: ۱۲۳۳)۔\nسببی نمازیں مثلاً: تحیۃ المسجد، نماز کسوف، نماز استسقاء وغیرہ بھی پڑھی جا سکتی ہیں۔ دیکھیے: توضیح الاحکام: (۲۷۵/۱)۔"}],[221,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس شخص نے اس حال میں رات گزاری کہ اس کے ہاتھ میں چکنائی کی بو تھی پھر اسے کوئی (تکلیف دہ) چیز پہنچ گئی تو وہ اپنے آپ ہی کو ملامت کرے۔”","",{"t":"کھانے کے بعد ہاتھ دھونے کی تاکید","k":"صحیح: سنن أبي داؤد، ح: ۳۸۵۲۔ سنن الترمذی، ح: ۱۸۵۹۔ سنن ابن ماجه، ح: ۳۲۹۷۔ الادب المفرد، ح: ۱۲۲۰۔ صحیح ابن حبان، ح: ۵۵۲۱۔ مسند ابن الجعد، ح: ۲۶۷۴۔ امالی ابی اسحاق الهاشمی، ح: ۷۸ (الشامله)۔","f":"کھانے کے بعد ہاتھوں کو خوب اچھی طرح دھو لینا چاہیے تا کہ کھانے کی چکنائی بالکل نہ رہے۔\nچکنائی کی بو والے ہاتھوں کے ساتھ سونا منع ہے۔\nغفلت کی وجہ سے پہنچنے والے نقصان پر اپنے آپ کو ملامت کرنا چاہیے تا کہ آئندہ محتاط رہا جائے۔"}],[222,"سیدنا بریدہ اسلمی رضی اللہ عنہ کہتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “جس کا میں ولی (دوست، محبوب) ہوں تو علی رضی اللہ عنہ بھی اس کا ولی (دوست، محبوب) ہے۔”","",{"t":"سیدنا علی رضی اللہ عنہ کی فضیلت","k":"صحیح: مسند احمد: ۳۵۸/۵۔ مولف کی سند میں ابن عیینہ مدلس کا عنعنہ ہے۔ جبکہ احمد وغیرہ کی سند میں امش مدلس کا عنعنہ ہے۔ شواہد کی بنا پر حدیث صحیح ہے۔ شواہد کے لیے دیکھیے: مسند البزار (ح: ۱۲۰۳ عن سعد، وسنده حسن) اور مسند احمد (۳۳۰/۱)،(۳۳۱) عن ابن عباس، وسنده صحیح۔","f":"اس حدیث میں سیدنا علی رضی اللہ عنہ کی فضیلت و منقبت بیان ہوئی ہے۔\nاس حدیث میں ولی کے معنی دوست اور محب کے ہیں نہ کہ امام، حاکم اور امیر کے۔\nحدیث کا مطلب یہ ہے کہ نبی صلی اللہ علیہ وسلم جس کے دوست اور محبوب ہیں، سیدنا علی رضی اللہ عنہ بھی اس کے دوست اور محبوب ہیں۔"}],[223,"سیدنا معاویہ بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ گرم کھانا نہ کھایا جائے یہاں تک کہ وہ ٹھنڈا ہو جائے۔","",{"t":"گرم کھانا کھانے کی ممانعت","k":"إسناده ضعیف جدا: محمد بن اسماعیل الجعفری اور عبداللہ بن سلمہ سخت ضعیف ہیں۔ نیز دیکھیے: حدیث نمبر ۲۱۰۔"}],[224,"سیدہ ام حبیبہ الجہینہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اگر چوپائے موت (کی سختی) کو جان لیں جیسے ابن آدم جانتا ہے تو تم کسی موٹے جانور کو نہ کھا پاؤ گے۔”","",{"t":"موت کی شدت","k":"إسناده ضعیف جدا: مسند الشهاب، ح: ۱۴۳۴۔ الضعیفة، ح: ۴۳۵۳۔ محمد بن اسماعیل الجعفری اور عبداللہ بن سلمہ سخت ضعیف ہیں۔"}],[225,"سیدنا ابو سعید الخدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس نے عاشوراء کے دن اپنے اہل و عیال پر فراخی کی اللہ اس پر سال بھر فراخی کرے گا۔”","",{"t":"عاشوراء کے دن اہل و عیال پر فراخی کرنا","k":"إسناده ضعیف جدا: المعجم الاوسط، ح: ۹۳۰۲۔ محمد بن اسماعیل اور عبد اللہ بن سلمہ سخت ضعیف ہیں۔ اس کے دیگر طرق و شواہد بھی ضعیف ہیں۔ دیکھیے: الضعیفة، ح: ۶۸۲۴۔"}],[226,"سیدنا صعصعہ بن ناجیہ رضی اللہ عنہ کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! مجھے وصیت کیجیے۔ آپ نے فرمایا: “ان چیزوں پر قابو پا لو جو تمہارے دونوں جبڑوں کے درمیان (زبان) اور دونوں پاؤں کے درمیان میں (شرمگاہ) ہے۔”","",{"t":"زبان اور شرم گاہ کی حفاظت","k":"إسناده ضعیف: تاریخ دمشق: ۴۸۰/۴۰۔ المختارة للضیاء، ح: ۶، جز: ۸۔ الضعیفة، ح: ۲۱۰۲۔ ابراہیم بن اسحاق اور عقال وغیرہ مجہول ہیں۔ صحیح البخاری کی حدیث (۶۸۰۷ عن سهل بن سعد رضی اللہ عنہ) اس سے بے نیاز کر دیتی ہے۔"}],[227,"سیدنا صعصعہ بن ناجیہ رضی اللہ عنہ کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! بسا اوقات میرے پاس اضافی چیز ہوتی ہے میں اسے مہمان اور مصیبت میں گھرے شخص کے لیے سنبھال کر رکھ لیتا ہوں۔ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “(اس کے حق دار) تمہاری ماں، تمہارا باپ، تمہاری بہن، تمہارا بھائی اور درجہ بدرجہ قریبی رشتے دار ہیں۔”","",{"t":"اضافی مال کے مستحق افراد","k":"إسناده کسابقه: المعجم الكبیر، ح: ۷۴۱۳۔ المختارة للضیاء، ح: ۴، جز: ۸۔ معرفة الصحابة لابی نعیم، ح: ۳۸۹۶۔"}],[228,"سیدنا ابن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جب تم تعریف کرنے والوں کو دیکھو تو ان کے چہروں پر مٹی ڈالو۔”","",{"t":"کسی کی رو برو تعریف کرنا","k":"صحیح: صحیح ابن حبان، ح: ۵۷۶۹۔ مسند احمد: ۹۴/۲۔ مسند ابن الجعد، ح: ۳۳۴۳۔ مسند عبد بن حمید، ح: ۸۱۲۔ الادب المفرد، ح: ۳۴۰۔ مسند البزار، ح: ۵۴۱۴۔ الصحیحة، ح: ۹۱۲۔ اس کے شواہد بھی ہیں۔","f":"امام نووی فرماتے ہیں: یہ ممانعت کی احادیث ہیں اور اس کے جواز میں بھی بہت سی صحیح احادیث آئی ہیں۔ علماء کہتے ہیں کہ ان احادیث میں جمع وتطبیق کی صورت یہ ہے کہ یوں کہا جائے کہ اگر ممدوح شخص (جس کی تعریف ہو رہی ہو) ایمان ویقین میں کامل ہو اور اسے ریاضت نفس کامل معرفت بھی حاصل ہو، جس کی وجہ سے اس تعریف سے اس کے فتنے میں مبتلا یا فریب نفس کا شکار ہونے کا اندیشہ نہ ہو اور نہ اس پر اس کا نفس ہی خوش ہو، تو اس صورت میں نہ (یہ تعریف) حرام ہے اور نہ مکروہ۔ اور اگر اس کی بابت ان مذکورہ چیزوں میں سے کسی کا اندیشہ ہو تو پھر اس کے منہ پر تعریف کرنا سخت ناپسندیدہ ہے اس تفصیل پر اس سلسلے میں وارد احادیث کو معمول کیا جائے گا اور جو احادیث جواز کے بارے میں ہیں ان میں سے ایک وہ ہے جس میں رسول اللہ صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ سے فرمایا تھا کہ مجھے امید ہے کہ تم بھی ان ہی میں سے ہو گے۔ یعنی ان لوگوں میں سے جن کو جنت میں داخلے کے وقت جنت کے تمام دروازوں سے بلایا جائے گا۔ اور دوسری حدیث ہے جس میں آپ نے ابو بکر رضی اللہ عنہ سے فرمایا کہ تم ان میں سے نہیں ہو یعنی ان لوگوں میں سے نہیں ہو جو اپنی شلواروں کو تکبر سے لٹکاتے ہیں۔ اور آپ نے عمر رضی اللہ عنہ سے فرمایا کہ شیطان جس راستے پر تجھ کو چلتا ہوا دیکھ لیتا ہے تو وہ اس راستے کو چھوڑ کر دوسرا راستہ اختیار کر لیتا ہے۔ اور جواز میں کثرت سے حدیثیں ہیں جن میں سے کچھ میں نے اپنی کتاب الاذکار میں ذکر کی ہیں۔ ریاض الصالحین: (۴۸۰)،(۴۷۹/۲)۔"}],[229,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “روحیں جمع شدہ لشکر ہیں، چنانچہ جن کا (عالم ارواح میں) باہم تعارف ہو گیا ان میں (یہاں دنیا میں) الفت پیدا ہو گئی اور جن میں (وہاں) اجنبیت رہی وہ (یہاں بھی) اختلاف کا شکار ہیں۔”","",{"t":"روحیں جمع شدہ لشکر ہیں","k":"صحیح البخاری، ح: ۳۳۳۶۔ مسند ابی یعلی، ح: ۴۳۸۷۔ مسند الشهاب، ح: ۲۷۴۔ امثال الحدیث لابی الشیخ، ح: ۱۰۰۔ شعب الایمان، ح: ۸۶۱۹۔","f":"اس حدیث کا معروف اور متبادر مفہوم یہی ہے۔ واللہ اعلم! کہ اللہ تعالیٰ نے جب روحیں پیدا کیں تو وہ عالم ارواح میں لشکروں کی طرح یکجا تھیں۔ وہاں جن کا آپس میں تعارف اور پہچان ہوئی وہ یہاں دنیا میں آکر ایک دوسری سے پیار محبت کرنے لگیں اور جن کا وہاں تعارف نہیں ہوا وہ یہاں آکر ایک دوسرے سے اجنبی رہیں بلکہ نفرت کرنے لگیں۔\nاس سے یہ بھی معلوم ہوا کہ روحیں بھی اپنا وجود رکھتی ہیں اور ان میں بھی عقل ونطق ہے۔"}],[230,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جو شخص اپنے مال کی حفاظت کرتا ہوا قتل ہو گیا وہ شہید ہے۔”","",{"t":"جس کے مال پر حملہ ہو وہ کیا کرے؟","k":"صحیح مسلم، ح: ۱۴۰۔ سنن النسائی، ح: ۴۰۸۷۔ مسند الشهاب، ح: ۳۴۰۔ مسند البزار، ح: ۸۹۶۶۔","f":"سنن النسائی میں ہے کہ ایک آدمی نے عرض کیا: اے اللہ کے رسول! بتلائیے اگر میرے مال پر حملہ ہو جائے تو؟ آپ نے فرمایا: “(حملہ آور کو اللہ تعالیٰ کا واسطہ دے (کہ مال نہ لوٹ)۔” اس نے کہا: اگر وہ (حملہ آور) نہ مانیں؟ آپ نے فرمایا: “پھر اللہ کا واسطہ دے۔” اس نے کہا: “اگر پھر بھی نہ مانیں؟” آپ نے فرمایا: “پھر اس سے لڑ، اگر تو قتل ہو گیا تو جنت میں جائے گا اور اگر تو نے ان کو مار دیا تو وہ دوزخ میں ہوں گے۔ سنن النسائی، ح: (۴۰۸۸)،(۴۰۸۷) وسنده صحیح”\nکسی دوسرے شخص کا مال ناحق چھینے والے کا خون مباح ہے اور اگر وہ اس لڑائی کے دوران مارا جائے تو دوزخی ہے اور اگر صاحب مال مارا جائے تو وہ شہید ہے۔\nاپنے مال کی حفاظت کرنا جائز ہے۔\nشہادت کے کئی مراتب ہیں، مال کی حفاظت کرتے ہوئے شہید ہونے والا حکمی شہید ہے۔\nراقم نے مسند الشہاب میں اس حدیث کی بایں الفاظ شرح کی ہے: اس حدیث مبارک سے پتا چلا کہ جو شخص کسی کے مال پر ناحق قبضہ کرنا چاہے۔ مال تھوڑا ہو یا زیادہ اور مالک کے لیے لڑائی کے بغیر کوئی چارہ نہ ہو تو ایسے شخص سے لڑنا جائز ہے اگر وہ مارا جائے تو اس کا خون رائیگاں ہے اور اگر اس لڑائی میں مالک مارا جائے تو اسے اللہ تعالیٰ اعزازی طور پر شہادت کا رتبہ عطا فرمائے گا کیونکہ اپنے مال کی حفاظت کرنا صرف مالک کا حق ہی نہیں بلکہ یہ اللہ تعالیٰ اور اس کے رسول کا حکم بھی ہے لہذا اللہ اور اس کے رسول کے حکم کی تعمیل میں مارا جانے والا شہید ہے۔"}],[231,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس نے پشیمان ہونے والے کی بیع کو فسخ کر دیا تو قیامت کے دن اللہ اس کی لغزشوں سے درگزر فرمائے گا۔”","",{"t":"اقالہ (بیع فسخ کرنا)","k":"صحیح: سنن أبي داؤد، ح: ۳۴۶۰۔ سنن ابن ماجه، ح: ۲۱۹۹۔ مسند الشهاب، ح: ۴۵۳۔ شرح مشکل الآثار، ح: ۵۲۹۱۔ صحیح ابن حبان، ح: ۵۰۲۹۔ مسند البزار، ح: ۸۹۶۷۔","f":"بیچ کرنے والے دونوں فریقوں کو سودا واپس کرنے کا اختیار اس وقت تک ہے جب تک جدا نہ ہوں۔ جب دونوں جدا ہو جائیں تو اب بیچ پختہ ہوگئی اور اختیار ختم ہو گیا۔ دیکھیے: صحیح البخاری، (ح: ۲۰۷۹)۔\nبیچ پختہ ہونے کے بعد فریقین میں سے اگر ایک شخص کسی وجہ سے نادم اور پشیمان ہو اور اپنے ساتھی سے سودا واپس کرنے کی درخواست کرے اور وہ سودا واپس کر کے بیچ ختم کر دے تو یہ اقالہ ہے۔ یعنی بیچ پختہ ہونے کے بعد فریق ثانی کی درخواست پر بیچ فسخ کرنا۔\nاقالہ ایک طرح کا احسان ہے جس کا صلہ قیامت کے دن گناہوں کی معافی کی صورت میں ملے گا۔"}],[232,"سیدنا ابو الدرداء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “رزق بندے کو اس کی موت سے بھی زیادہ شدت سے طلب کر لیتا ہے۔”","",{"t":"رزق بندے کو تلاش کر لیتا ہے","k":"إسناده ضعیف: السنة لابن ابی عاصم، ح: ۲۶۴۔ مسند الشهاب، ح: ۲۴۱۔ ولید بن مسلم تدلیس تسویہ کرنے والے نے اپنے سماع مسلسل کی صراحت نہیں کی۔"}],[233,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس شخص نے اس حال میں رات گزاری کہ اس کے ہاتھ میں چکنائی کی بو تھی پھر اسے کوئی (تکلیف دہ) چیز پہنچ گئی تو وہ اپنے آپ ہی کو ملامت کرے۔”","",{"t":"کھانے کے بعد ہاتھ دھونے کی تاکید","k":"صحیح: دیکھیے: حدیث نمبر ۲۲۱۔"}],[234,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “میری امت قیامت کے دن وضو کے نشانوں سے سفید چہرے والے سفید ہاتھ پاؤں والے ہوں گے۔”","",{"t":"وضو کی فضیلت","k":"صحیح البخاری، ح: ۱۳۶۔ صحیح مسلم، ح: ۲۴۶۔ سنن النسائی، ح: ۱۵۰۔ سنن ابن ماجه، ح: ۴۳۰۶۔ المعجم الاوسط، ح: ۹۲۱۴۔ مسند احمد: ۳۳۴/۲۔ مسند الشهاب، ح: ۲۹۰۔","f":"قیامت کے دن محمد صلی اللہ علیہ وسلم کی امت کے چہرے اور ہاتھ پاؤں وضو کے نشانات کی وجہ سے سفید اور چمک رہے ہوں گے۔\nروز قیامت اعضاء وضو کا چمکنا امت محمد صلی اللہ علیہ وسلم کے ساتھ خاص ہے، اس میں دوسری امتیں شریک نہیں۔ دیکھیے: صحیح مسلم، (ح: ۲۴۷)۔\nروز قیامت جن کے چہرے سفید ہوں گے وہ اللہ تعالیٰ کی رحمت میں ہوں گے اور اس میں ہمیشہ رہیں گے۔ (دیکھیے: سورہ آل عمران: ۱۰۷)۔\nاس حدیث میں وضو اور نماز کی فضیلت ہے، بے نماز، فساق جنہوں نے دنیا میں نماز چھوڑنے کو عادت بنا لیا تھا، وہ اس چمک یعنی امت مسلمہ کی پہچان کے نشان سے محروم ہوں گے۔\nسیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم قبرستان کی طرف گئے، آپ نے فرمایا: “اے مومن لوگوں کے شہر! اور بے شک ہم ان شاء اللہ تمہیں آملیں گے، میری خواہش تھی کہ میں اپنے بھائیوں کو دیکھ لیتا۔” صحابہ نے عرض کی: کیا ہم آپ کے بھائی نہیں؟ آپ نے فرمایا: “تم تو میرے صحابہ ہو، میرے بھائی وہ ہیں جو ابھی پیدا نہیں ہوئے اور میں حوض کوثر پر ان کا پیش رو ہوں گا۔” صحابہ نے عرض کی: اللہ کے رسول! آپ اپنی امت کے ان لوگوں کو کیسے پہچانیں گے جو آپ کے بعد آئیں گے؟ فرمایا: “بتاؤ اگر ایک آدمی کے گھوڑے سفید ماتھے سفید ہاتھ پاؤں والے ہوں جبکہ دوسرے گھوڑے خالص سیاہ ہوں تو کیا وہ اپنے گھوڑے کو نہیں پہچانے گا؟” صحابہ نے عرض کی: کیوں نہیں، (ضرور پہچان لے گا) آپ نے فرمایا: “بلاشبہ وہ (میری امت) قیامت کے دن سفید چہروں، سفید ہاتھ پاؤں کے ساتھ آئیں گے اور میں حوض کوثر پر ان کا پیش رو ہوں گا۔ سنو! کچھ لوگ میرے حوض سے اس طرح دور ہوں گے جس طرح بھٹکا ہوا اونٹ دور کر دیا جاتا ہے۔ میں انہیں آواز دوں گا کہ ادھر آؤ۔ ارشاد ہوگا: انہوں نے آپ کے بعد اپنا دین بدل لیا تھا۔ پھر میں کہوں گا: دور ہو جاؤ، دور ہو جاؤ۔” (صحیح مسلم، ح: ۲۴۹)۔"}],[235,"سیدنا ابن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جو بھی اونٹوں، گائیوں اور بکریوں کا مالک ان کی زکوۃ ادا نہیں کرتا تو روز قیامت اسے ان (جانوروں) کے لیے اوندھا لٹایا جائے گا۔ وہ اپنے کھروں کے ساتھ اسے روندیں گے اور اپنے سینگوں کے ساتھ اسے ٹکریں ماریں گے، یہاں تک کہ لوگوں کے درمیان فیصلہ کر دیا جائے۔”","",{"t":"زکوۃ نہ دینے کی سزا","k":"صحیح: اس کے شواہد بھی ہیں، دیکھیے: صحیح البخاری، ح: ۱۴۰۲ عن ابی ہریرہ۔","f":"زکوۃ ایک مالی عبادت ہے جو ہر صاحب نصاب مسلمان پر فرض ہے۔\nجانوروں کی زکوۃ نہ دینے والے قیامت کے دن لوگوں کا حساب مکمل نہ ہونے تک عذاب میں مبتلا رہیں گے۔\nمذکورہ وعید اونٹوں، گائیوں اور بکریوں کی زکوۃ کے وجوب پر دلالت کرتی ہے۔"}],[236,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جب تم میں سے کوئی شخص (روزے کی حالت میں) بھول کر کھا لے یا پی لے تو اسے چاہیے کہ اپنا روزہ پورا کرے کیونکہ اللہ ہی نے اسے کھلایا اور پلایا ہے۔”","",{"t":"روزہ کی حالت میں بھول کر کھا پی لینا","k":"صحیح البخاری، ح: ۱۹۳۳۔ صحیح مسلم، ح: ۱۱۵۵۔ سنن الترمذی، ح: ۷۲۱۔ سنن ابن ماجه، ح: ۱۶۷۳۔ مسند احمد: ۴۹۱/۲۔","f":"روزے کے دوران کھانا پینا منع ہے۔\nبھول کر کھانے پینے سے روزہ نہیں ٹوٹتا اور نہ اس کی قضا دینی پڑتی ہے۔\nجان بوجھ کر کھا پی لینے سے روزہ ٹوٹ جاتا ہے اور اس کی قضا دینا لازم ہے۔\nاللہ تعالیٰ اپنے بندے کو مختلف طریقوں سے کھلاتا پلاتا ہے۔"}],[237,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جنت اور دوزخ نے مباحثہ کیا تو جنت نے کہا: اے میرے رب! میرے اندر کمزور اور کم حیثیت والے یا ان سے بھی نچلے طبقے کے لوگ داخل ہوں گے، اور دوزخ نے کہا: میرے اندر جبار اور متکبر لوگ داخل ہوں گے۔ تو اللہ تعالیٰ نے جنت سے فرمایا: تو میری جنت ہے: میں جسے چاہوں گا تجھ میں داخل کروں گا اور دوزخ سے فرمایا: تو میرا عذاب ہے میں جسے چاہوں گا تیرے ذریعے عذاب دوں گا اور تم دونوں میں سے ہر ایک کے لیے بھرنا ہوگا۔”","",{"t":"جنت اور دوزخ کا مباحثہ","k":"صحیح البخاری، ح: ۴۸۵۰۔ صحیح مسلم، ح: ۲۸۴۶۔ سنن الترمذی، ح: ۲۵۶۱۔ صحیح ابن حبان، ح: ۷۴۷۷۔ مسند احمد: ۵۰۷/۲۔","f":"جنت اور دوزخ دونوں اللہ تعالیٰ کی مخلوق ہیں اس وقت بالفعل موجود ہیں، یہ دونوں اور ان میں رہنے والے ہر گز فنا نہیں ہوں گے۔ (دیکھیے: رسالہ نجاتیہ در عقائد حدیثیہ، ص: ۸۴۔ عقیدة السلف للصابونی: ۱۰۳)۔\nجنت اللہ تعالیٰ کی رحمت ہے اور دوزخ اللہ تعالیٰ کا عذاب ہے۔\nجنت میں اللہ تعالیٰ کے فرمانبردار کمزور اور سادہ لوح لوگ ہوں گے جبکہ دوزخ میں اللہ تعالیٰ کے نافرمان، متکبر اور سرکش لوگ ہوں گے۔\nمعلوم یہ ہوتا ہے کہ ۔ واللہ اعلم! جنت اور دوزخ کی طرف سے یہ ایک قسم کی شکایت کا اظہار تھا کہ جنت نے کہا کہ میرے اندر کمزور و ناتواں لوگ ہیں اور دوزخ نے کہا کہ مجھے صرف لٹیروں، سرکشوں اور متکبروں کے ساتھ خاص کیا گیا ہے تو اللہ تعالیٰ نے دونوں کی گفتگو اور شکایت سن کر فرمایا کہ تم دونوں میری مخلوق ہو، دونوں برابر ہو، بات صرف اتنی ہے کہ تم میں سے ایک کے ساتھ میرا عدل و انصاف وابستہ ہے جو دوزخ ہے اور دوسری سے میرا انعام و اکرام وابستہ ہے جو جنت ہے۔\nاللہ تعالی فعال لما یرید ہے جو چاہے کرتا ہے۔"}],[238,"بقیہ کہتے ہیں کہ میں نے امام شعبہ سے سعید بن بشیر کے متعلق پوچھا تو انہوں نے فرمایا: (وہ) صدوق ہیں۔","",{"t":"سعید بن بشیر","k":"إسناده صحیح: الجرح والتعدیل لابن ابی حاتم: (۱۴۳/۱)،(۶/۴)۔","f":"سعید بن بشیر الازدی مولی بنی نصر مختلف فیہ راوی ہے لیکن جمہور محدثین نے ان کو ضعیف کہا ہے، جیسا کہ ابن ملقن فرماتے ہیں: والاکثرون على تضعیفه (البدر المنیر: ۸۵/۹)۔"}],[239,"ابو الضحی کہتے ہیں کہ ہم ابو عبیدہ بن عبد اللہ بن مسعود کے پاس تھے تو انہوں نے کہا: عبد اللہ رضی اللہ عنہ نے مجھے فرمایا: بے شک سورہ الاحزاب، سورہ البقرہ کے برابر تھی۔ تو ابو عبیدہ نے کہا: آپ نے سچ فرمایا ہے۔","",{"t":"سورہ الاحزاب کی فضیلت","k":"صحیح: اس کا شاہد بھی ہے۔ دیکھیے: المستدرک للحاکم: ۴۱۵/۲۔ صحیح ابن حبان، ح: ۴۴۲۸۔ المعجم الاوسط، ح: ۴۳۵۲۔ تهذیب الآثار (مسند عمر)، ح: ۱۲۳۰ عن ابی بن کعب رضی اللہ عنہ و سنده حسن۔","f":"مطلب یہ ہے کہ سورہ الاحزاب نزول کے وقت قرات میں سورہ البقرہ جتنی لمبی تھی لیکن پھر بعد میں اس کا اکثر حصہ منسوخ ہو گیا۔ منسوخ ہونے والے حصہ میں آیت رجم بھی تھی: ﴿الشیخ والشیخة اذا زنیا فارجموهما نکالا من الله والله عزیز حکیم﴾۔ اب اس میں تہتر (۷۳) آیات باقی ہیں۔ واللہ اعلم!"}],[240,"سیدنا ابن عباس رضی اللہ عنہما اللہ تعالیٰ کے فرمان (ترجمہ): “اے ایمان والو! تمہارے لیے حلال نہیں کہ زبردستی عورتوں کے وارث بن جاؤ” کی تفسیر میں فرماتے ہیں کہ عرب لوگ جب آدمی مر جاتا تو کہتے: اس کے بعد ہم اس کی بیوی کے زیادہ حق دار ہیں تو اس سلسلے میں یہ آیت نازل ہوئی۔","",{"t":"﴿یَا أَیُّهَا الَّذِینَ آمَنُوا لَا یَحِلُّ لَکُمْ أَن تَرِثُوا النِّسَاءَ﴾ [النساء: ۱۹] کی تفسیر","k":"صحیح البخاری، ح: ۴۵۷۹۔ سنن أبي داؤد، ح: ۲۰۸۹۔ السنن الكبری للنسائی، ح: ۱۱۰۲۸۔ جامع البیان للطبری، ح: ۸۸۷۹۔ تفسیر القرآن لابن ابی حاتم، ح: ۲۵۷۸ من تفسیر سوره النساء۔","f":"دور جاہلیت میں یہ دستور تھا کہ جب کوئی آدمی مر جاتا تو اس کے رشتے دار اس کی بیوی کے حق دار بن بیٹھتے ان میں سے کوئی چاہتا تو اس سے نکاح کر لیتا یا اپنی مرضی کے مطابق کسی دوسری جگہ اس کا نکاح کر دیتا، چاہتے تو بغیر شادی کے اسے پڑا رہنے دیتے، اس زیادتی کے تدارک کے سلسلے میں یہ آیت نازل ہوئی۔ (دیکھیے: صحیح البخاری، ح: ۴۵۷۹)۔\nدور جاہلیت میں عورت کو بھی ترکے کا مال سمجھا جاتا تھا جس پر میت کے قریبی رشتے دار بھائی وغیرہ کا حق ہوتا، اس سلسلے میں عورت خود یا عورت کے وارث کچھ اختیار نہ رکھتے، اسلام نے آکر عورت کو پوری پوری عزت دی اور اسے آزادانہ حقوق دیے۔"}],[241,"سعید بن جبیر سے مروی ہے کہ وہ سیدنا ابن عباس رضی اللہ عنہما کی خدمت میں حاضر ہوئے اور ان سے حرام چیزوں کے متعلق دریافت کیا تو انہوں (ابن عباس رضی اللہ عنہما) نے ان کے سامنے یہ آیت پڑھی (ترجمہ): “کہہ دیجیے: میں اس وحی میں، جو میری طرف کی گئی ہے کسی کھانے والے پر کوئی چیز حرام نہیں پاتا جسے وہ کھائے، سوائے اس کے کہ وہ مردار ہو یا بہایا ہوا خون ہو یا خنزیر کا گوشت ہو کہ بے شک وہ گندگی ہے یا نا فرمانی کا باعث ہو، جس پر غیر اللہ کا نام پکارا گیا ہو پھر جو کوئی مجبور کر دیا جائے اس حال میں کہ نہ بغاوت کرنے والا ہو اور نہ حد سے بڑھنے والا تو بے شک آپ کا رب بے حد بخشنے والا بڑا رحم کرنے والا ہے۔” (الانعام: ۱۴۵)","",{"t":"حرام چیزیں","k":"إسناده صحیح","f":"دور جاہلیت میں مشرکین نے بعض چیزوں کو از خود حلال اور حرام قرار دے رکھا تھا اللہ تعالیٰ نے سورہ الانعام کی اس آیت (۴۵) میں ان کا رد فرمایا اور بتایا کہ حلت وحرمت کا اختیار صرف اللہ تعالیٰ کے پاس ہے، وہ وحی کے ذریعے اپنے انبیاء کو ان پر مطلع فرماتا ہے لہذا وحی کے ذریعے ہی کسی چیز کی حلت و حرمت معلوم ہوتی ہے اور رسول اللہ صلی اللہ علیہ وسلم سے فرمایا کہ آپ کہہ دیں کہ مجھ پر جو وحی اتری ہے اس میں تو یہ چار چیزیں حرام ہیں: (۱) مردار (۲) بہا ہوا خون (۳) خنزیر (۴) اور ہر وہ چیز جس پر غیر اللہ کا نام پکارا گیا ہو۔ یہ سورت مکی ہے اس لیے اس میں صرف ان چار چیزوں کا ذکر ہے بعد میں نازل ہونے والی سورتوں میں اور بھی کئی چیزوں کا ذکر ہے جیسے سورہ المائدہ کی آیت نمبر ۳ میں ہے اور اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے بھی وحی کی روشنی میں کئی جانوروں کا حرام ہونا بتایا جن کی تفصیل احادیث میں ہے۔\nسعید بن جبیر جلیل القدر تابعی ہیں اور سیدنا ابن عباس رضی اللہ عنہما کے شاگرد ہیں انہوں نے جب حرام چیزوں کے بارے میں سیدنا ابن عباس رضی اللہ عنہما سے دریافت کیا تو آپ نے موقع و محل اور سائل کے سوال کا اندازہ لگاتے ہوئے سورہ الانعام کی مذکورہ آیت کی طرف ان کی توجہ مبذول کروا دی کہ حلت و حرمت کا اختیار اللہ تعالیٰ کے پاس ہے لہذا وہی چیزیں حرام ہیں جن کا ذکر قرآن مجید یا نبی صلی اللہ علیہ وسلم کی احادیث میں ملتا ہے۔"}],[242,"نعیم بن حماد کہتے ہیں کہ میں نے ابوبکر بن عیاش کو یہ کہتے ہوئے سنا: موسیٰ بن طریف۔ اور وہ (موسیٰ) بنی ضبہ میں سے تھے، غیر صدوق ہیں۔","",{"t":"موسیٰ بن طریف","k":"إسناده حسن","f":"موسیٰ بن طریف الاسدی الکوفی ایک متروک راوی ہے۔\nامام ابوبکر بن عیاش نے اس پر جرح کی کہ وہ غیر صدوق ہے۔"}],[243,"سیدنا انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس نے مجھ پر ایک مرتبہ درود بھیجا اللہ اس پر دس رحمتیں نازل کرے گا۔”","",{"t":"درود کی فضیلت","k":"صحیح: سنن النسائی، ح: ۱۲۹۸۔ الادب المفرد، ح: ۶۴۳۔ مسند احمد: ۱۰۲/۳۔ صحیح مسلم (ح: ۴۰۸) میں اس کا شاہد بھی ہے۔","f":"نبی کریم صلی اللہ علیہ وسلم پر درود بھیجنے کی بڑی اہمیت و فضیلت ہے، راقم نے اس پر ایک مضمون قلم بند کیا ہے، جو سطور ذیل میں ہدیہ قارئین کیا جا رہا ہے۔\nنبی کریم صلی اللہ علیہ وسلم محسن انسانیت ہیں۔ آپ نے انسانیت کو کفر و ضلالت کے اندھیروں سے نکال کر صراط مستقیم پر گامزن کیا۔ تمام انسانیت پر بالعموم اور مسلمانوں پر بالخصوص آپ کے ان گنت احسانات ہیں۔ ان احسانات کا تقاضا ہے کہ ہر چیز سے بڑھ کر آپ سے محبت کی جائے ، آپ کی اطاعت کی جائے اور آپ پر زیادہ سے زیادہ\nدرود و سلام بھیجا جائے۔ درود کا معنی و مفہوم:\nدرود کو عربی میں ”صلاة“ کہتے ہیں۔ جس کے معنی: نماز، دعا، تعظیم، رحمت اور استغفار وغیرہ کے ہیں۔ علامہ ابو السعادات المبارک بن محمد الجزری (م: ۶۰۶ھ ) لکھتے ہیں:\nالصلاة والصلوات وهى العبادة المخصوصة وأصلها في اللغة الدعاء فَسُمِّيَتْ ببعض أجزائها، وقيل: إن أصلها في اللغة التعظيم وسميت العبادة المخصوصة صلاة لما فيها من تعظيم الرب تعالى ، وقوله في التشهد الصلوات لله ، أى الأربعة التى يُراد بها تعظيم اللہ تعالى هو مُسْتَحِقُهَا لا تليقُ بأحدٍ سواه ، فأما قولنا: أللهم صل على محمد فمعناه: عظمه في الدنيا بإعلاء ذكره وإظهار دعوته وإبقاء شريعته وفي الآخرة بتشفيعه في أمته وتضعيف أجره ومثوبته ، وقيل : المعنى لما أمر اللہ سبحانه بالصلاة عليه ولم نَبْلُغ قدر الواجب من ذلك أَحَلْنَاه على اللہ وقلنا: اللہم صل أنت على محمد ، لأنك أعلم بما يَلِيقُ به\nصلاۃ اور صلوات ایک مخصوص عبادت (نماز) کا نام ہے۔ لغت میں اس کا اصل معنی دعا ہے۔ اس کے بعض حصے (دعا ہونے) کی وجہ سے اسے یہ نام دیا گیا ہے۔ اور کہا گیا ہے کہ لغت میں اس کا اصل معنی تعظیم ہے۔ مخصوص عبادت (نماز) کو یہ نام ( صلاة ) اس لیے دیا گیا ہے کہ اس میں رب تعالیٰ کی تعظیم ہوتی ہے اور تشہد میں یہ کہنا \" و الصلوات لله“ اس سے اللہ تعالیٰ کی تعظیم کے وہ کلمات مراد ہیں جن کا اس کے سوا کوئی مست نہیں۔ اور رہا ہمارا یہ کہنا: \"اللہم صلى على محمد تو اس کا معنی یہ ہے کہ دنیا میں آپ کا ذکر بلند کر کے آپ کی دعوت کو عام کر کے، آپ کی شریعت کو باقی رکھ کر اور آخرت میں آپ کی اپنی امت کے حق میں سفارش کے ساتھ اور ان کے اجر و\n- ثواب کو دو گنا چوگنا کر کے آپ کو عظمت عطا فرما۔ اور کہا گیا ہے کہ اس کا معنی یہ ہے کہ جب اللہ سبحانہ و تعالیٰ نے آپ پر درود بھیجنے کا حکم دیا جبکہ ہم کما حقہ درود نہیں بھیج سکے تو ہم نے یہ معاملہ اسی کے سپرد کر دیا اور کہا: اے اللہ ! آپ خود ہی محمد صلی اللہ علیہ وسلم پر درود بھیجیں۔ کیونکہ آپ صلی اللہ علیہ وسلم کے مرتبہ کے موافق درود آپ ہی بہتر جانتے ہیں ۔ “ (النهاية : ۴۶/۳)\nدرود کی اہمیت:\nنبی کریم صلی اللہ علیہ وسلم پر درود بھیجنے کی بڑی اہمیت ہے۔ اس کی بڑی تاکید فرمائی گئی ہے۔ اللہ تعالیٰ کا ارشاد ہے: إن اللہ وَمَلَئِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَأْيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًاه (الأحزاب : (۵۶) ” بے شک اللہ تعالیٰ اور اس کے فرشتے نبی پر درود بھیجتے ہیں، اے ایمان والو! تم بھی ان پر درود بھیجو اور خوب سلام بھیجو۔“ اس آیت میں اللہ تعالیٰ نے نبی صلی اللہ علیہ وسلم پر اپنے اور فرشتوں کے درود بھیجنے کے ذکر کے بعد عام مومنوں کو آپ صلی اللہ علیہ وسلم کی ذات گرامی پر درود و سلام بھیجنے کا حکم فرمایا ہے۔\nامام ترمذی (م: ۲۷۹ھ) فرماتے ہیں: وروى عن سفيان الثوري وغير واحد من أهل العلم ، قالو: صلاة الرب الرحمة وصلاة الملائكة الإستغفار“ ”امام سفیان ثوری اور کئی ایک اہل علم سے مروی ہے کہ رب تعالیٰ کے درود سے مراد رحمت ہے اور فرشتوں کے درود سے مراد استغفار ہے۔\n(سنن الترمذی، تحت ح: ۴۸۵)\nنبی کریم صلی اللہ علیہ وسلم نے بھی اپنی امت کو درود پڑھنے کا حکم فرمایا ہے۔ چنانچہ سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: (لا تَجْعَلُوا بُيُوتِكُمْ قُبُورًا وَلَا تَجْعَلُوا قَبْرِى عِيْدًا وَصَلُّوْا عَلَيَّ فَإِنَّ صَلَاتَكُمْ تَبْلُغُنِي حَيْثُ كُنتُم )) \" تم اپنے گھروں کو قبرستان نہ بناؤ اور میری قبر کوعید نہ بناؤ اور مجھ پر درود بھیجو کیونکہ تم جہاں کہیں بھی ہو گے تمہارا درود مجھ تک پہنچ جائے گا۔ (سنن أبی داود : ۲۰۴۲ وسندہ حسن) ہمارے شیخ حافظ زبیر علی زئی رحمہ اللہ فرماتے ہیں: درود پہنچنے سے مراد یہ نہیں کہ آپ صلی اللہ علیہ وسلم بنفس نفیس\nسنتے ہیں بلکہ اس کا مطلب یہ ہے کہ فرشتوں کے ذریعے سے آپ کی خدمت میں درود پہنچایا جاتا ہے...\nدرود\n(فضائل درود و سلام، ص: ۱۱)\n- امام ابن سیرین رحمہ اللہ سے مروی ہے کہ وہ چھوٹے بچے کے لیے دعا مانگتے اور استغفار کرتے جس طرح بڑے کے لیے استغفار کرتے تھے، اس پر انہیں کہا گیا کہ اس بچے کا تو کوئی گناہ ہی نہیں ہے، تو انہوں نے فرمایا: النبی صلی اللہ علیہ وسلم قد غفر اللہ له ما تقدم من ذنبه وما تاخر وقد أمرت أن أصلى عليه اللہ تعالیٰ نے اگلی پچھلی تمام لغزشیں معاف فرمادی ہیں اور بلاشبہ مجھے (اس کے باوجود بھی) آپ پر درود بھیجنے کا\nحکم دیا گیا ہے۔ (فضل الصلاة لقاضي إسماعيل بن إسحاق : ۷۸ وسنده صحيح)\nدرود کی فضیلت:\nاحادیث مبارکہ میں آپ صلی اللہ علیہ وسلم پر درود بھیجنے کی بڑی فضیلت بیان ہوئی ہے۔\n۱ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللہُ عَلَيْهِ عَشْرًا) جس نے مجھ پر ایک مرتبہ درود بھیجا اللہ تعالیٰ اس پر دس رحمتیں نازل فرمائے گا۔“ (صحیح مسلم : ۴۰۸)\n۲ سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((مَنْ صَلَّى عَلَيَّ مَرَّةً وَاحِدَةً، كَتَبَ اللہُ عَزَّوَجَلَّ لَهُ بِهَا عَشْرَ حَسَنَاتٍ)) جس نے مجھے پر ایک مرتبہ درود بھیجا اللہ عز وجل اس کے\nبدلے اس کے لیے دس نیکیاں لکھے گا۔ (مسند احمد : ۲۶۲/۲ و سندہ حسن)\n:۳ سیدنا ابو طلحہ رضی اللہ عنہ سے روایت ہے کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور آپ کے چہرے پر بشارت (خوشی ) نظر آ رہی تھی۔ ہم نے عرض کیا: ہم آپ کے چہرے پر بشارت (خوشی) دیکھ رہے ہیں تو آپ نے فرمایا: ((إِنَّهُ أَتَانِى الْمَلَكُ ، فَقَالَ : يَا مُحَمَّدُ إِنَّ رَبَّكَ يَقُولُ : أَمَا يُرْضِيْكَ أَنَّهُ لا يُصَلَّى عَلَيْكَ أَحَدٌ إِلَّا صَلَّيْتُ عَلَيْهِ عَشْرًا وَلَا يُسَلِّمُ عَلَيْكَ أَحَدٌ إِلَّا سَلَّمْتُ عَلَيْهِ عَشْرًا ) ”میرے پاس فرشتہ آیا اور اس نے کہا: اے محمد ! بے شک آپ کا رب فرماتا ہے: کیا آپ اس پر راضی نہیں کہ جو کوئی بھی آپ پر درود پڑھے تو میں اس پر دس رحمتیں نازل فرماؤں اور جو کوئی آپ پر سلام کہے تو میں اس پر دس (دفعہ ) سلامتی نازل فرماؤں ۔ (سنن النسائى : ۱۲۸۴؛ فضل الصلاة على النبي : ۲\nوسنده حسن)\n:۴ سیدنا انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((مَنْ صَلَّى عَلَيَّ صَلاةٌ وَاحِدَةً صَلَّى اللہُ عَلَيْهِ عَشْرَ صَلَوَاتٍ وَحُطَّتْ عَنْهُ عَشْرُ خَطِيئَاتٍ وَرُفِعَتْ لَهُ عَشْرُ دَرَجَاتٍ))\n۲۲ ”جس نے مجھ پر ایک بار درود بھیجا اللہ تعالیٰ اس پر دس رحمتیں نازل کرے گا اس کی دس خطائیں معاف کر دی\nجائیں گی اور اس کے دس درجے بلند کیے جائیں گے۔“ (سنن النسائی : ۱۲۹۸ وسندہ صحیح) :۵ سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((أَولَى النَّاسِ بِي يَوْمَ الْقِيَامَةِ اَكْثَرُهُمْ عَلَيَّ صَلَاةٌ)) ”قیامت کے دن مجھ سے لوگوں میں سے سب سے زیادہ قریب وہ\nہوگا جو مجھے پر سب سے زیادہ درود بھیجتا ہے ۔ (سنن الترمذي : ۴۸۴ وسنده حسن\nدرود کے الفاظ: سیدنا عبد اللہ بن مسعود رضی اللہ عنہ اور فرماتے ہیں: إِذَا صَلَّيْتُمْ عَلَى رَسُولِ اللہ فَأَحْسِنُوا الصَّلاةَ عَلَيْهِ ، فَإِنَّكُمْ لا تَدْرُونَ لَعَلَّ ذَلِكَ يُعْرَضُ عَلَيْهِ \" جب تم رسول اللہ صلی اللہ علیہ وسلم پر درود بھیجو تو اچھی طرح سے بھیجو کیونکہ تم نہیں جانتے شاید اسے آپ صلی اللہ علیہ وسلم پر پیش کیا جائے (سنن ابن ماجه : ۹۰۶- المعجم الكبير -۸۵۹۴ الدعوات الكبير للبيهقي : ۱۷۷ وسنده حسن)\nصحیح اور حسن روایات میں درود کے جتنے بھی الفاظ وارد ہوئے ہیں وہ سب اچھے اور بہترین ہیں، لہذا ان میں سے جو بھی پڑھ لیں وہ صحیح اور باعث اجر وثواب ہے۔ بعض الفاظ درج ذیل ہیں: (۱) جناب عبد الرحمن بن ابی لیلی کہتے ہیں کہ ایک مرتبہ میری سیدنا کعب بن عجرہ رضی اللہ عنہ سے ملاقات ہوئی تو انہوں نے فرمایا: کیا میں تمہیں ایک تحفہ نہ دوں جو میں نے نبی صلی اللہ علیہ وسلم سے حاصل کیا ہے؟ میں نے کہا: کیوں نہیں۔ آپ مجھے وہ تحفہ عنایت کریں، تو انہوں نے فرمایا: ہم نے رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا: اللہ کے رسول ! ہم آپ پر اور آپ کے اہل بیت پر درود کس طرح بھیجیں کیونکہ اللہ تعالیٰ نے آپ پر سلام بھیجنے کا طریقہ تو خود ہی ہمیں سکھا دیا ہے۔ آپ نے فرمایا: تم یوں کہو: ((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ . اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ\nوَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ )) \" اے اللہ! محمد صلی اللہ علیہ وسلم پر اور آل محمد صلی اللہ علیہ وسلم پر رحمت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر رحمت نازل فرمائی۔ بے شک آپ بے حد تعریف والے، بڑی بزرگی والے ہیں۔ اے اللہ! محمد صلی اللہ علیہ وسلم پر اور آل محمد صلی اللہ علیہ وسلم پر برکت نازل فرما جس طرح آپ نے ابراہیم پر اور ابراہیم کی آل پر برکت نازل فرمائی، بے شک آپ بے حد تعریف والے، بڑی بزرگی والے ہیں۔“ (صحیح البخاری : ۳۳۷۰)\n(۲) سیدنا طلحہ بن عبید اللہ رضی اللہ عنہ فرماتے ہیں کہ ہم نے کہا: اے اللہ کے رسول! آپ پر درود کس طرح پڑھنا ہے؟ آپ نے فرمایا: تم کہو: ((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ )) اے اللہ! محمد پر اور آل محمد پر رحمت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر رحمت نازل فرمائی، بے شک آپ بے حد تعریف والے، بڑی بزرگی والے ہیں اور محمد پر اور آل محمد پر برکت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر برکت نازل فرمائی۔ بے شک آپ بے حد تعریف والے، بڑی بزرگی والے ہیں۔“\n(سنن النسائى : ۱۲۹۱- مسند احمد : ۱۶۲/۱ و سنده حسن\n(۳) سیدنا ابو حمید الساعدی رضی اللہ عنہ سے مروی ہے کہ صحابہ کرام نے عرض کیا: اے اللہ کے رسول! ہم آپ پر کس طرح درود بھیجیں ؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم کہو: ((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ )) اے اللہ! محمد صلی اللہ علیہ وسلم، ان کی ازواج اور ان کی ! اولاد پر رحمت نازل فرما جس طرح آپ نے آل ابراہیم پر رحمت نازل فرمائی ۔ اور محمد صلی اللہ علیہ وسلم، ان کی ازواج اور اولاد پر برکت نازل فرما جس طرح آپ نے آل ابراہیم پر برکت نازل فرمائی۔ بے شک آپ بے حد تعریف والے، بڑی بزرگی والے ہیں۔“ (صحیح البخاری : ۳۳۶۹) (۴) سیدنا ابو سعید الخدری رضی اللہ عنہ فرماتے ہیں کہ ہم نے کہا: اے اللہ کے رسول ! یہ آپ پر سلام ہے، لیکن ہم درود کس طرح پڑھیں ؟ آپ نے فرمایا: تم کہو: ((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَ آلِ إِبْرَاهِيمَ)) ”اے اللہ! اپنے بندے اور اپنے رسول محمد پر رحمت نازل فرما جس طرح آپ نے ابراہیم پر رحمت نازل فرمائی اور محمد پر اور آل محمد پر برکت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر برکت نازل فرمائی ۔“ (صحیح البخاری : ۶۳۵۸)\n(۵) سیدنا ابو مسعود الانصاری رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے جبکہ ہم سعد\nبن عبادہ کی مجلس میں تھے۔ سیدنا بشیر بن سعد نے آپ سے عرض کیا: اے اللہ کے رسول ! اللہ تعالیٰ نے ہمیں آپ\nپر درود بھیجنے کا حکم دیا ہے تو ہم کس طرح آپ پر درود بھیجیں؟ یہ سن کر رسول اللہ صلی اللہ علیہ وسلم خاموش رہے حتی کہ ہم نے خواہش کی کہ وہ (بشیر ) آپ سے سوال نہ ہی کرتے ۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم کہو: ((اللَّهُمَّ صَلِ عَلى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلى آلِ إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، فِى الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَّجِيدٌ )) ”اے اللہ ! محمد پر اور آل محمد پر رحمت نازل فرما جس طرح آپ نے آل ابراہیم پر رحمت نازل فرمائی۔ اور محمد پر اور آل محمد پر برکت نازل فرما جس طرح آپ نے آل ابراہیم پر جہانوں میں برکت نازل فرمائی، بے شک آپ بے حد تعریف والے، بڑی بزرگی والے ہیں۔ جبکہ سلام اسی طرح ہے جسے تم جان چکے ہو۔“ (صحیح مسلم : ۴۰۵) (۶) موسیٰ بن طلحہ کہتے ہیں کہ میں نے سیدنا زید بن خارجہ رضی اللہ عنہ سے دریافت کیا تو انہوں نے فرمایا: میں نے بھی رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا تھا تو آپ نے فرمایا تھا کہ تم مجھ پر درود بھیجو اور خوب محبت سے دعا کرو اور تم کہو: ((اللہم صل علی محمد وآل محمد)) “اے اللہ! محمد پر اور آل محمد پر رحمت نازل فرما۔”\n(سنن النسائی: ۱۲۹۳ وسندہ حسن)\n(۷) سیدنا ابو مسعود عقبہ بن عمرو رضی اللہ عنہ کہتے ہیں کہ ایک آدمی آیا اور آکر رسول اللہ صلی اللہ علیہ وسلم کے سامنے بیٹھ گیا ہم بھی آپ کے پاس تھے، اس نے کہا: اے اللہ کے رسول ! جہاں تک آپ پر سلام بھیجنے کا تعلق ہے تو وہ ہم جان چکے ہیں۔ لیکن جب ہم اپنی نماز میں آپ پر درود بھیجنا چاہیں تو کس طرح بھیجیں؟ اللہ آپ پر رحمت نازل فرمائے۔ آپ خاموش رہے۔ حتی کہ ہم نے خواہش کی کہ یہ آدمی آپ سے نہ ہی سوال کرتا۔ پھر آپ نے فرمایا : جب تم مجھ پر درود بھیجو تو تم کہو: ((اللَّهُمَّ صَلَّ عَلَى مُحَمَّدٍ النَّبِيِّ الأمّى وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى اِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ ، وَبَارِكْ عَلَى مُحَمَّدٍ النَبِيِّ الْأُمِي، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ اِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ )) اے اللہ! نبی امی محمد پر اور آل محمد پر رحمت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر رحمت نازل فرمائی اور نبی امی محمد پر برکت نازل فرما جس طرح آپ نے ابراہیم پر اور آل ابراہیم پر برکت نازل فرمائی۔ بے شک آپ بے حد تعریف والے، بڑی بزرگی والے ہیں۔\"\n(مسند أحمد: ۱۱۹/۴ وسندہ حسن)\n(۸) سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ ہم نے کہا: اے اللہ کے رسول! ہم کس طرح آپ پر درود بھیجیں؟ آپ نے فرمایا: تم کہو: ((اللَّهُمَّ صَلَّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى\nآلِ مُحَمَّدٍ كَمَا صَلَّيْتَ وَبَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ )) اے اللہ ! محمد پر اور آل محمد پر رحمت نازل فرما اور محمد پر اور آل محمد پر برکت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر رحمت نازل فرمائی اور برکت نازل فرمائی۔ بے شک آپ بے حد تعریف والے۔ بڑی بزرگی والے\nہیں ۔ اور سلام اسی طرح ہے جسے تم جانتے ہو۔ (شرح مشکل الآثار للطحاوي : ۲۲۴۰ وسنده حسن) (۹) سیدنا ابن مسعود رضی اللہ عنہ فرماتے ہیں: جب تم رسول اللہ صلی اللہ علیہ وسلم پر درود بھیجو تو اچھی طرح درود بھیجو کیونکہ تم نہیں جانتے شاید اسے آپ صلی اللہ علیہ وسلم پر پیش کیا جائے ۔ لوگوں نے کہا: آپ ہمیں سکھا دیں۔ انہوں نے فرمایا: تم کہو: ((اللَّهُمَّ اجْعَلْ صَلَاتَكَ ، وَرَحْمَتَكَ ، وَبَرَكَاتِكَ ، عَلَى سَيِّدِ الْمُرْسَلِينَ، وَإِمَامٍ الْمُتَّقِينَ ، وَخَاتَمِ النَّبِيِّينَ ، مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ، إِمَامِ الْخَيْرِ ، وَقَائِدِ الْخَيْرِ ، وَرَسُوْلِ الرَّحْمَةِ ، اللَّهُمَّ ابْعَثْهُ مَقَامًا مَحْمُودًا يَغْبِطُهُ بِهِ الْأَوَّلُونَ وَالْآخِرُونَ ، اللہُمَّ صَلَّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ)) یا اللہ ! تو اپنی رحمتیں اور برکتیں نازل فرما، رسولوں کے سردار، متقین کے امام اور آخری نبی محمد صلی اللہ علیہ وسلم پر جو تیرے بندے، رسول، نیکی کے امام ورہبر اور رسولِ رحمت ہیں۔ یا اللہ! انہیں اس مقام محمود پر فائز فرما، جس کی وجہ سے سب اگلے پچھلے لوگ ان پر رشک کریں ۔ یا اللہ! محمد پر اور آل محمد پر اسی طرح رحمت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر رحمت نازل فرمائی۔ بے شک آپ بڑی تعریف والے بڑی بزرگی والے ہیں ۔ یا اللہ ! محمد صلی اللہ علیہ وسلم اور آل محمد صلی اللہ علیہ وسلم پر اسی طرح برکت نازل فرما جس طرح آپ نے ابراہیم اور آل ابراہیم پر برکت نازل فرمائی۔ بے شک آپ بڑی تعریف والے بڑی بزرگی والے ہیں ۔ “ (سنن\nابن ماجه : ۹۰۶- المعجم الكبير : ۴۵۹۴- الدعوات الكبير للبيهقي : ۱۷۷ وسنده حسن) (۱۰) سیدنا انس بن مالک رضی اللہ عنہ کہتے ہیں کہ سیدنا ابو ذر رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے (حدیث معراج) بیان کرتے ہوئے فرمایا۔ پھر جبریل مجھے لے کر آسمان دنیا کی طرف چڑھے جب ہم آسمان دنیا پر پہنچے تو جبریل علیہ السلام نے آسمان دنیا کے خازن سے کہا: دروازہ کھولیں۔ انہوں نے کہا: آپ کون ہیں؟ فرمایا: جبریل ہوں۔ انہوں نے کہا: آپ کے ہمراہ کوئی ہے؟ انہوں نے فرمایا: ہاں، محمد صلی اللہ علیہ وسلم ہیں. (صحیح البخاری: ۳۴۹، صحیح مسلم: ۱۶۳)\nصلی اللہ علیہ وسلم والے الفاظ کے ساتھ نبی صلی اللہ علیہ وسلم پر درود بھیجنا تو اتر کے ساتھ کتب احادیث میں\nثابت ہے۔\n(۱۱) جلیل القدر تابعی یزید بن عبد اللہ بن الشخیر سے مروی ہے کہ وہ (صحابہ و تابعین ) یہ الفاظ کہنا پسند کرتے تھے: ((اللَّهُمَّ صَلَّ عَلَى مُحَمَّدٍ النَّبِيِّ الْأُمِّي عَلَيْهِ السَّلَامُ)) \"اے اللہ ! آپ نبی امی محمد صلی اللہ علیہ وسلم پر درود و سلام بھیجیں۔ (فضل الصلوة على النبي صلی اللہ علیہ وسلم : ۶۰ وسنده صحيح)\nدرود کے مواقع:\nاحادیث مبارکہ میں نبی صلی اللہ علیہ وسلم پر درود بھیجنے کے بہت سارے مواقع کا ذکر ملتا ہے۔ بعض ایسے ہیں جن میں درود پڑھنا واجب ہے اور بعض ایسے ہیں جن میں مستحب ہے۔ جیسا کہ امام ابن کثیر (م : ۷۷۴ھ) فرماتے ہیں: فإنه قد ورد الأمر بالصلاة عليه في أوقات كثيرة فمنها واجب ومنها مستحب» «حقيقت یہ ہے کہ بہت سارے اوقات ایسے ہیں جن میں آپ پر درود بھیجنے کا حکم آیا ہے پھر ان میں سے کچھ واجب ہیں اور کچھ مستحب ہیں ۔ (تفسیر القرآن : ۲۲۰/۵)\nواجب مواقع:\nجن اوقات میں آپ صلی اللہ علیہ وسلم پر درود بھیجنا واجب ہے، وہ درج ذیل ہیں:\n(۱) ذکر نبی صلی اللہ علیہ وسلم: نبی صلی اللہ علیہ وسلم کا ذکر سن کر آپ پر درود بھیجنا فرض ہے۔\nسیدنا کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: (( أَحْضُرُوا المِنبَر )) منبر لاؤ \" ہم منبر\nلائے ۔ آپ صلی اللہ علیہ وسلم جب پہلی سیڑھی پر چڑھے تو فرمایا: ”آمین“ پھر دوسری پر چڑھے تو فرمایا: ”آمین“ پھر تیسری سیڑھی پر چڑھے تو فرمایا ”آمین“ پھر جب آپ نیچے تشریف لائے تو ہم نے عرض کیا: اللہ کے رسول ! آج ہم نے آپ سے ایسی چیز سنی ہے جو پہلے نہیں سنتے تھے؟ آپ نے فرمایا: ((انَّ جِبْرِيلَ عَ عَرَضَ لِي ، فَقَالَ: بُعْدًا لِمَنْ أَدْرَكَ رَمَضَانَ فَلَم يُغْفَرْ لَهُ ، قُلْتُ: آمين ، فَلَمَّا رَقِيْتُ الثَّانِيَةَ قَالَ: بُعْدًا لِمَنْ ذُكِرتَ عِنْدَهُ فَلَمْ يُصَلَّ عَلَيْكَ، قُلْتُ : آمِينَ ، فَلَمَّا رَقِيْتُ الثَّالِثَةَ قَالَ : بُعْدًا لِمَنْ أَدْرَكَ اَبَوَاهُ الْكِبَرَ عِنْدَهُ اَوْ اَحَدُهُمَا فَلَمْ يُدْخِلاهُ الْجَنَّةَ ، قُلْتُ : آمین)) \" بے شک جبریل علیہ السلام میرے پاس تشریف لائے انہوں نے کہا: وہ شخص ہلاک ہو جس نے رمضان پا لیا پھر بھی اس کی بخشش نہ ہو سکی۔ میں نے کہا: آمین۔ پھر جب میں دوسری سیڑھی پر چڑھا تو جبریل نے کہا: وہ شخص ہلاک ہو جس کے پاس آپ کا\nمحمر لابن الأعرابي -۱-\nذکر ہوا اور اس نے آپ پر درود نہ بھیجا۔ میں نے کہا: آمین۔ پھر جب میں تیسری سیڑھی پر چڑھا تو جبریل نے کہا: وہ شخص ہلاک ہو جس نے اپنے والدین یا ان میں سے کسی ایک کو پایا پھر وہ اسے جنت میں داخل نہ کراسکیں۔ تو میں نے کہا: آمین ۔“ (المستدرك للحاكم : ۱۵۳/۴ وصححه ووافقه الذهبي ـ و حسنه شيخنا زبیر علی زئی فی تخريج فضل الصلاة على النبي : (۱۹) سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((رَغمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ، وَرَغِمَ أَنْفُ رَجُلٍ دَخَلَ عَلَيْهِ رَمَضَانُ ثُمَّ انْسَلَخَ قَبْلَ أَنْ يُغْفَرَ لَهُ، وَرَغِمَ أَنْفُ رَجُلٍ أَدْرَكَ عِنْدَهُ أَبَوَاهُ الْكِبَرَ فَلَمْ يُدْخِلاهُ الْجَنَّةَ \"اس شخص کی ناک خاک آلود ہو جس کے پاس میرا ذکر ہو لیکن اس نے مجھ پر درود نہیں بھیجا۔ اس شخص کی ناک خاک آلود ہو جس کی زندگی میں رمضان آیا پھر اس کی بخشش سے پہلے ہی گزر گیا اور اس شخص کی ناک خاک آلود ہو جو اپنے پاس اپنے والدین کو بڑھاپے میں پائے پھر وہ اسے جنت میں داخل نہ کر سکیں۔ ا\n(سنن الترمذي : ۳۵۴۵- فضل الصلاة على النبي صلی اللہ علیہ وسلم : ۱۶ وسنده حسن)\nسیدنا حسین بن علی بن ابی طالب رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((الْبَخِيْلُ الَّذِى مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ )) وہ شخص بخیل ہے جس کے سامنے میرا ذکر کیا گیا اور اس نے مجھ پر درود\nنہ بھیجا۔ (سنن الترمذی : ۳۵۴۶ وسنده حسن)\nامام ابن کثیر رحمہ اللہ (م: ۴۷۷ھ) لکھتے ہیں: ” وهذا الحديث والذي قبله دليل على وجوب الصلاة عليه كلما ذكر وهو مذهب طائفة من العلماء منهم الطحاوي والحليمي یہ اور اس سے پہلی حدیث آپ صلی اللہ علیہ وسلم پر درود بھیجنے کے وجوب کی دلیل ہے جب بھی آپ کا ذکر ہو اور علماء کی\nایک جماعت کا یہی مذہب ہے جن میں طحاوی اور حلیمی شامل ہیں ۔ (تفسیر القرآن العظيم : ۲۱۹/۵) ہیں۔ علامہ حسین بن حسن اکلیمی (م: ۴۰۳ ) رقم طراز ہیں: \"قد تظاهرت الأخبار بوجوب الصلاة عليه كلما جرى ذكره فإن كان يثبت إجماع يلزم الحجة بمثله على أن ذلك غير فرض وإلا فهو فرض بہت ساری احادیث اس بات پر دلالت کرتی ہیں کہ جب بھی آپ کا ذکر ہو آپ پر درود بھیجنا واجب ہے۔ ہاں اگر معتبر اجماع سے یہ ثابت ہو جائے کہ یہ فرض نہیں تو (پھر یہ مستحب ہوگا ) ورنہ یہ فرض\nہی ہے۔ (شعب الایمان : ۱۴۹/۳\nمعلوم ہوا کہ نبی صلی اللہ علیہ وسلم کا ذکر آنے پر آپ کا نام پر درود بھیجنا فرض ہے۔ جتنی بار بھی آپ صلی اللہ علیہ وسلم کا ذکر ہو آپ پر درود پڑھا جائے۔ تاہم بعض اہل علم کا کہنا ہے کہ اگر کسی مجلس میں بار بار آپ کا ذکر آتا ہو تو ایسی صورت میں اگر ایک مرتبہ بھی پڑھ لیا جائے تو یہ کفایت کر جائے گا۔ چنانچہ امام ترمذی (م: ۲۷۹ھ) فرماتے ہیں: \"ویروی عن بعض أهل العلم قال: إذا صلى الرجل على النبي مرة في المجلس أجزأ عنه ما كان في ذلك المجلس“ اور بعض اہل علم سے مروی ہے کہ انہوں نے کہا کہ جب آدمی مجلس میں نبی صلی اللہ علیہ وسلم پر ایک بار درود بھیج دے تو جب تک وہ اس مجلس میں رہے گا یہ اس کے لیے کافی ہے۔\n(سنن الترمذي، تحت ح : ۳۵۴۵)\n(۲) مجلس ہر مجلس و محفل اور میٹنگ میں نبی صلی اللہ علیہ وسلم پر کم از کم ایک بار درود بھیجنا واجب ہے۔\nسیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ((مَا فَعَدَ قَوْمٌ مَقْعَدًا لا يَذْكُرُونَ فِيهِ اللہ عَزوجل، وَيُصَلُّوْنَ عَلَى النَّبِيِّ صلی اللہ علیہ وسلم إِلَّا كَانَ عَلَيْهِمْ حَسْرَةً يَوْمَ الْقِيَامَةِ وَإِنْ دَخَلُوا الْجَنَّةَ لِلثَّوَابِ (( لوگ کسی جگہ بیٹھیں اس میں اللہ کا ذکر نہ کریں اور نہ نبی صلی اللہ علیہ وسلم پر درود بھیجیں تو یہ (بیٹھک) ان کے لیے قیامت کے دن ضرور حسرت کا باعث ہوگی خواہ وہ دیگر ثواب کی وجہ سے جنت میں داخل بھی ہو جائیں۔“\n(مسند احمد : ۴۶۳/۲ وسنده صحيح)\nسیدنا ابو سعید رضی اللہ عنہ فرماتے ہیں: ((مَا مِنْ قَوْمٍ يَقْعُدُ ثُمَّ يَقُومُونَ وَلا يُصَلُّونَ عَلَى النَّبِيِّ إِلَّا كَانَ عَلَيْهِمْ يَوْمَ الْقِيَامَةِ حَسْرَةً وَإِنْ دَخَلُوا الْجَنَّةَ لِلثَّوَابِ جو لوگ بیٹھیں پھر اٹھ جائیں اور نبی صلی اللہ علیہ وسلم پر درود نہ پڑھیں تو قیامت کے دن وہ (مجلس ) ان کے لیے حسرت کا باعث ہوگی خواہ وہ ثواب کی وجہ سے جنت\nمیں چلے بھی جائیں ۔ (مسند ابن الجعد : ۷۳۹- فضل الصلاة على النبي صلی اللہ علیہ وسلم : ۵۵ وسنده صحيح) شیخ الالبانی رحمہ اللہ (م : ۱۴۲۰ھ) فرماتے ہیں: لقد دل هذا الحديث الشريف وما في معناه على وجوب ذكر اللہ سبحانه، وكذا الصلاة على النبي في كل مجلس، ودلالة الحديث على ذلك من وجوه . بلاشبہ یہ حدیث شریف اور اس کے ہم معنی احادیث ہر مجلس میں اللہ\nسبحانہ کے ذکر اور نبی صلی اللہ علیہ وسلم پر درود کے وجوب پر دلالت کرتی ہے۔ (الصحيحة : ۱۶۱/۱) .....\nمزید فرماتے ہیں: ”ثانيا: قوله (( وَإِنْ دَخَلُوا الْجَنَّةَ، لِلثَّوَاب))، فانه ظاهر في كون تارك الذكر والصلاة عليه صلی اللہ علیہ وسلم ، يستحق دخول النار ، وان كان مصيره\nالى الجنة ثوابا على ايمانه..... فعلى كل مسلم ان يتنبه لذلك، ولا يغفل عن ذكر اللہ عز وجل والصلاة على نبيه في كل مجلس يقعده والا كان عليه ترة وحسرة يوم\nالقيامة آپ صلی اللہ علیہ وسلم کا فرمان ہے کہ اگر چہ وہ ثواب کی بنا پر جنت میں داخل ہو بھی ہو جائیں۔ یہ الفاظ اس بات میں واضح ہیں کہ ذکر الہی اور نبی صلی اللہ علیہ وسلم پر درود کا تارک جہنم میں داخلے کا مستحق ہے، اگر چہ اپنے ایمان کے ثواب کی بنا پر وہ جنت میں داخل بھی ہو جائے گا۔ اس لیے ہر مسلمان کو چاہیے کہ وہ اس وعید سے خبردار رہے اور اپنی کسی بھی مجلس و محفل میں ذکر الہی اور نبی صلی اللہ علیہ وسلم پر درود سے غافل نہ رہے۔ ورنہ یہ کوتاہی قیامت کے دن اس کے لیے نقصان اور حسرت کا باعث ہوگی ۔“ (الصحيحة : ۱۶۱/۱)\n(۳) آخری تشہد . آخری تشہد میں بھی نبی کریم صلی اللہ علیہ وسلم پر درود بھیجنا واجب ہے۔\nسیدنا فضالہ بن عبید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو نماز میں دعا کرتے ہوئے سنا، اس نے اللہ تعالیٰ کی بزرگی بیان کی تھی اور نہ ہی نبی صلی اللہ علیہ وسلم پر درود بھیجا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((عَجِلَ هذا)) اس نے جلد بازی کی ہے۔ پھر آپ نے اسے بلایا اور اسے یا کسی دوسرے شخص سے فرمایا: ((إِذَا صَلَّى أَحَدُكُمْ فَلْيَبْدَأْ بِتَحْمِيدِ رَبِّهِ جَلَّ وَعَزَّ وَالثَّنَاءِ عَلَيْهِ ثُمَّ يُصَلِّى عَلَى النَّبِي ثُمَّ يَدْعُو بَعْدُ بِمَا شَاءَ ”جب تم میں سے کوئی شخص نماز پڑھے تو اسے چاہیے کہ اپنے رب عزوجل کی بزرگی اور ثناء سے ابتداء کرے پھر نبی صلی اللہ علیہ وسلم پر درود بھیجے پھر اس کے بعد جو چاہے دعا مانگے۔“\n(سنن أبي داود : ۱۴۸۱ وسنده حسن)\nبعض اہل علم نے اس حدیث سے یہ مسئلہ اخذ کیا ہے کہ نماز کے آخری تشہد میں نبی صلی اللہ علیہ وسلم پر درود بھیجنا واجب ہے۔ جیسا کہ حافظ ابن کثیر (تفسیر القرآن : ۲۱۲/۵) اور حافظ ابن حجر (الدارية في تخريج أحاديث الهداية:\n۱۵۷/۱) وغیرہ ہیں۔\n۱۵۷/۱)\nامام آجری (م ۳۶۰ھ) فرماتے ہیں: ” واعلموا - رحمنا اللہ وإياكم - لو ان مصليا صلى صلاة فلم يصل على النبي فيها فى تشهده الاخير وجب عليه إعادة الصلاة\" \"او اللہ! جان لیجئے ! اللہ تعالیٰ ہم پر اور تم پر رحم فرمائے۔ اگر کوئی نمازی نماز پڑھے اور اس کے آخری تشہد میں نبی صلی اللہ علیہ وسلم پر درود نہ پڑھے تو اس پر نماز دہرانا واجب ہے۔“ (الشريعة ، ص : ۳۳۵) امام شافعی (م: ۲۰۴ھ) فرماتے ہیں: وإن تشهد ولم يصل على النبي أو صلى على\nالنبي ولم يتشهد فعليه الإعادة حتى يجمعهما جميعا \" اور اگر کوئی شخص تشہد پڑھے اور نبی صلی اللہ علیہ وسلم پر درود نہ بھیجے یا نبی صلی اللہ علیہ وسلم پر درود تو بھیجے مگر تشہد نہ پڑھے تو اس پر نماز لوٹانا واجب ہے یہاں تک کہ وہ ان دونوں کو جمع کرے ۔ “ (الام : ۳۸۹/۱)\nامام ابو اسحاق ابراہیم بن احمد المروزی (م: ۳۴۰ھ) فرماتے ہیں: \"أنا أعتقد أن الصلاة على آل النبي هو واجبة في التشهد الأخير من الصلاة “ ” میں یہ اعتقاد رکھتا ہوں کہ نماز کے آخری تشہد میں\nآل نبی صلی اللہ علیہ وسلم پر درود بھیجنا واجب ہے ۔ (شعب الإيمان : ۱۵۰/۳ تحت ح : ۱۴۸۵ وسنده حسن) (۴) نماز جنازہ نماز جنازہ میں درود کے وجوب اور عدم وجوب میں اختلاف ہے۔ چنانچہ شیخ الاسلام ابن القیم (م : ۷۵۱ھ) فرماتے ہیں: \"الموطن الرابع من مواطن الصلاة عليه صلاة\nالجنازة بعد التكبيرة الثانية لا خلاف فى مشروعيتها فيها واختلف في توقف صحة الصلاة عليها، فقال الشافعي وأحمد في المشهور من مذهبهما، إنها واجبة في الصلاة لا تصح الابها، ورواه البيهقي عن عبادة بن الصامت وغيره من الصحابة وقال مالك و أبو حنيفة تستحب وليست بواجبة وهو وجه لإصحاب الشافعى آپ صلی اللہ علیہ وسلم پر درود بھیجنے کا چوتھا مقام نماز جنازہ بعد از تکبیر ثانیہ ہے۔ اس کی مشروعیت میں تو کوئی اختلاف نہیں لیکن اس مسئلہ میں اختلاف ہے کہ اس کے بغیر نماز ہو جاتی ہے یا نہیں؟ امام شافعی واحمد کا مشہور مذہب یہ ہے کہ نما ز میں یہ واجب ہے اس کے بغیر نماز درست نہیں۔ امام بیہقی نے سیدنا عبادہ بن صامت اور دیگر صحابہ سے ایسا ہی روایت کیا ہے جبکہ امام مالک وابو حنیفہ کہتے ہیں کہ مستحب ہے واجب نہیں، کچھ اصحاب شافعی بھی یہی کہتے ہیں۔\"\nدرود\n(جلاء الأفهام، ص : ۱۱۷۹)\nاس مسئلے میں ہمیں جو بات زیادہ پختہ اور راج معلوم ہوتی ہے وہ وجوب کی ہے۔ واللہ اعلم سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ انہوں نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے میت پر نماز جنازہ کے متعلق دریافت کیا تو انہوں نے فرمایا: واللہ! میں آپ کو بتاتا ہوں۔ آپ تکبیر سے آغاز کریں پھر نبی صلی اللہ علیہ وسلم پر درود بھیجیں اور (پھر) یہ دعا پڑھیں: ((اللَّهُمَّ إِنَّ عَبْدَكَ فَلَانًا كَانَ لا يُشْرِكُ بِكَ شَيْئًا ن أَعْلَم بِهِ إِنْ كَانَ مُحْسِنًا فَزِد فِى اِحْسَانِهِ وَإِنْ كَانَ مُسِينًا فَتَجَاوَزْ عَنْهُ، اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلا تُضِلَّنَا بَعْدَهُ)) ”اے اللہ ! بے شک تیرا فلاں بندہ تیرے ساتھ کسی چیز کو شریک نہیں کرتا تھا تو اس سے بخوبی واقف !\nہے اگر وہ نیک تھا تو اس کی نیکی میں اضافہ فرما اور اگر وہ گناہ گار تھا تو اس سے درگز رفرما۔ اے اللہ ! ہمیں اس کے اجر سے محروم نہ رکھنا اور اس کے بعد ہمیں گمراہ نہ کر دینا ۔ (السنن الكبرى للبيهقي : ۶۹۶۴ وسنده صحيح) سیدنا ابوامامہ بن سہل بن حنیف رضی اللہ عنہ فرماتے ہیں: \"السُّنَّةُ فِي الصَّلاةِ عَلَى الْجَنَازَةِ أَنْ يُكَبِّرَ ثُمَّ يَقْرَأَ بِأم القرآن ثُمَّ يُصَلِّى عَلَى النَّبِي ثُمَّ يُخْلِصُ الدُّعَاءَ لِلْمَيِّتِ وَلا يَقْرَأُ إِلَّا فِى التَّكْبِيرَةِ الأولى ثُمَّ يُسَلِّمُ فِي نَفْسِهِ عَنْ يَمِينِهِ\" \"نماز جنازہ میں سنت طریقہ یہ ہے کہ آدمی تکبیر کہے پھرام القرآن (سورۃ فاتحہ پڑھے پھر نبی صلی اللہ علیہ وسلم پر درود بھیجے پھر میت کے لیے اخلاص کے ساتھ دعا کرے، قرآت صرف پہلی تکبیر میں کرے، پھر اپنے دل میں اپنی دائیں جانب سلام پھیر دے۔\"\n(المنتقی لابن الجارود: ۵۴۰ وسندہ صحیح)\nامام شعبی رحمہ اللہ فرماتے ہیں: \"أَوَّلُ تَكْبِيرَةٍ مِنَ الصَّلَاةِ عَلَى الْجَنَازَةِ ثَنَاء عَلَى اللَّهِ عز وجل وَالثَّانِيَةُ صَلَاةٌ عَلَى النَّبِي وَالثَّالِثَةُ دُعَاء لِلْمَيِّتِ وَالرَّابِعَةُ السَّلامُ ”نماز جنازہ کی پہلی تکبیر میں اللہ کی ثناء (سورہ الفاتحہ) ہے، دوسری میں نبی صلی اللہ علیہ وسلم پر درود ہے، تیسری میں میت کے لیے دعا ہے اور چوتھی میں سلام ہے۔ (فضل الصلاة على النبي صلی اللہ علیہ وسلم : ۹۱ وسنده صحيح)\nمستحب مواقع:\nجن مواقع میں آپ صلی اللہ علیہ وسلم پر درود بھیجنا مستحب ہے وہ درج ذیل ہیں:\n(۱) بعد از اذان اذان سن کر نبی کریم صلی اللہ علیہ وسلم پر درود بھیجنا مستحب ہے۔\nسیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: ((إِذَا سَمِعْتُمْ الْمُؤَذِنَ فَقُولُوا مِثْلَ مَا يَقُولُ ، ثُمَّ صَلُّوا عَلَيَّ ، فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلوةٌ صَلَّى اللہُ عَلَيْهِ بِهَا عَشْرًا ، ثُمَّ سَلُوا اللہَ لِيَ الْوَسِيلَةَ ، فَإِنَّهَا مَنْزِلَةٌ فِى الْجَنَّةِ ، لَا تَنْبَغِي إِلَّا لِعَبْدِ مِنْ عِبَادِ اللَّهِ ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ، فَمَنْ سَأَلَ اللہَ لِيَ الْوَسِيلَةَ حَلَّتْ لَهُ الشَّفَاعَةُ)) \"جب تم مؤذن کو ( اذان دیتے ہوئے) سنو تو وہی کلمات کہو جو مؤذن کہہ رہا ہو، پھر مجھ پر درود بھیجو، کیونکہ جو شخص مجھ پر ایک مرتبہ درود بھیجتا ہے، اللہ تعالیٰ اس کے بدلے اس شخص پر دس رحمتیں نازل کرتا ہے۔ پھر اللہ تعالیٰ سے میرے لیے ” الوسیلہ طلب کرو۔ الوسیلہ جنت میں ایک مخصوص مقام ہے، جو اللہ کے تمام بندوں میں سے صرف ایک بندے کو نصیب ہوگا اور میں امید کرتا ہوں کہ وہ ایک بندہ میں ہوں گا۔ جو شخص میرے لیے الوسیلہ طلب کرے\nگا، اسے میری شفاعت نصیب ہوگی ۔“ (صحیح مسلم : ۳۸۴، سنن ابی داؤد ، : ۵۲۳) اس حدیث سے معلوم ہوا کہ اذان کے بعد درود پڑھنا مستحب اور اجر عظیم کا باعث ہے۔ تاہم یہ بات یاد رہے کہ جس طرح ہمارے ہاں آج کل اذان سے قبل درود پڑھا جاتا ہے، نہ یہ طریقہ درست ہے اور نہ یہ الفاظ\nثابت ہیں۔\nبریلوی مکتب فکر کے معروف عالم دین علامہ غلام رسول سعیدی صاحب لکھتے ہیں: اس بات پر غور کرنا چاہیے کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے مدینہ منورہ میں دس سال اذان دی جاتی رہی۔ خلفاء راشدین کے دور میں تمہیں سال اذان دی جاتی رہی اور سو سال تک عہد صحابہ و تابعین میں اذان دی جاتی رہی اور کسی دور میں بھی اذان سے پہلے یا بعد فصل کر کے جہراً درود شریف نہیں پڑھا گیا اور آٹھ صدیوں تک مسلمان اسی طریقے سے اذان دیتے رہے تو آیا اذان دینے کا افضل طریقہ وہ ہے جس طریقے سے عہد رسالت اور عہد صحابہ میں اذان دی جاتی تھی یا وہ افضل طریقہ ہے جو آٹھویں صدی میں ایجاد ہوا؟ (شرح صحیح مسلم : ۱۰۹۴/۱)\n(۲) آغاز خطبہ خطبہ کے آغاز میں درود پڑھنا مستحب ہے۔ سیدنا ابو جحیفہ رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا علی رضی اللہ عنہ منبر پر تشریف لائے ، انہوں نے اللہ کی حمد وثناء کی اور نبی صلی اللہ علیہ وسلم پر درود بھیجا اور فرمایا: اس امت میں نبی صلی اللہ علیہ وسلم کے بعد بہترین شخصیت ابوبکر ہیں اور دوسرے نمبر پر عمر ”\nہیں، اور فرمایا: اللہ تعالیٰ جہاں چاہے خیر و بھلائی رکھ دیتا ہے۔“ (مسند أحمد : ۱۰۶/۱ وسنده صحيح) جعفر بن برقان کہتے ہیں کہ عمر بن عبد العزیز نے لکھا: اما بعد ! لوگوں میں سے بعض ایسے ہیں جو آخرت کے اعمال سے دنیا چاہتے ہیں اور لوگوں میں سے بعض قصہ گو خطباء نے اپنے خلفاء اور امراء کے لیے نبی کا نام پر درود جیسے درود کو ایجاد کر لیا ہے۔ لہذا جب میرا یہ خط تمہارے پاس پہنچے تو تم انہیں حکم دو کہ وہ نبیوں پر درود بھیجیں اور عام مسلمانوں کے لیے دعا کریں۔ اس کے علاوہ سب کچھ چھوڑ دیں۔\n(فضل الصلاة على النبي : ۷۶ وسنده صحيح) امام شافعی فرماتے ہیں: \" وأقل ما يقع عليه اسم خطبة من الخطبتين أن يحمد اللہ تعالى ويصلى على النبي ويوصى بتقوى اللہ ويدعو في الآخرة لأن معقولاً أن الخطبة\nجمع بعض الكلام من وجوه إلى بعض وهذا أوجز ما يجمع من الكلام “ ”جمعہ کے دونوں خطبوں میں سے خطبہ کا لفظ کم از کم جس چیز پر بولا جاتا ہے وہ یہ ہے کہ اللہ کی حمد بیان کرے۔ نبی صلی اللہ علیہ وسلم پر درود\nبھیجے۔ اللہ کے تقویٰ اور پر ہیز گاری کی وصیت کرے اور آخر میں دعا کرے کیونکہ عقلا بھی خطبہ کلام کی بعض اقسام کو جمع کرنے کا نام ہے اور کلام کے جمع کرنے کا یہ سب سے مختصر طریقہ ہے۔\"\n(معرفة السنن والآثار للبيهقي : ۶۴۶۷ وسنده صحيح)\n(۳) پہلا تشہد: نماز کے پہلے تشہد میں درود پڑھنا مستحب ہے۔ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں:\nكُنَّا نُعِدُ لِرَسُولِ اللہِ صَلَّى اللہُ عَلَيْهِ وَسَلَّمَ سِوَاكَهُ وَطَهُورَهُ، فَيَبْعَثُهُ اللہُ عَزَّوَجَلَّ لَمَّا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ ، فَيَسْتَاكُ وَيَتَوَضَّأُ، وَيُصَلِّى تِسْعَ رَكَعَاتٍ، لا يَجْلِسُ فِيهِنَّ إِلَّا عِنْدَ الثَّامِنَةِ ، وَيَحْمَدُ اللہَ، وَيُصَلِّي عَلَى نَبِيِّهِ ، وَيَدْعُو بَيْنَهُنَّ ، وَلا يُسَلِّمُ تَسْلِيمًا ، ثُمَّ يُصَلِّي التَّاسِعَةَ وَيَقْعَدُ ـ وَذَكَرَ كَلِمَةٌ نَحْوَهَا وَيَحْمَدُ اللہَ، وَيُصَلِّي عَلَى نَبِيِّهِ ، وَيَدْعُو ثُمَّ يُسَلِمُ تَسْلِيمًا يُسْمِعُنَا ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ قَاعِدٌ))\nہم رسول اللہ صلی اللہ علیہ وسلم کے لیے مسواک اور وضو کا پانی تیار رکھتے پھر جب اللہ تعالیٰ چاہتا رات میں آپ کو اٹھا دیتا تو آپ مسواک کرتے وضو کرتے اور نو رکعت (وتر) پڑھتے ۔ ان میں صرف آٹھویں رکعت کے بعد بیٹھتے ، اللہ کی حمد کرتے ، نبی صلی اللہ علیہ وسلم پر درود بھیجتے۔ ان کے درمیان دعا کرتے اور سلام نہ پھیرتے ، پھر نویں رکعت پڑھتے اور اللہ کی حمد کرتے ، اس کے نبی (یعنی اپنے آپ پر درود\nبھیجتے اور دعا کرتے پھر سلام پھیرتے ۔ ہمیں (سلام) سنا دیتے پھر دو رکعتیں بیٹھ کر ادا کرتے ۔“\n(سنن النسائی: ۱۷۲۱ وصححہ شیخنا زبیر علی زئی رحمہ اللہ)\nعلامہ نووی رحمہ اللہ (م: ۶۷۶ھ) فرماتے ہیں: ” وأما التشهد الأول: فلا تجب فيه الصلاة على\nالنبي بلا خلاف ، وهل تستحب؟ فيه قولان، أصحهما تستحب “ ” اور رہا پہلا تشہد ، تو بلا\nاختلاف اس میں نبی صلی اللہ علیہ وسلم پر درود بھیجنا واجب نہیں ہے۔ لیکن کیا مستحب ہے؟ اس میں دو قول ہیں، جن میں\nترین یہ ہے کہ مستحب ہے۔ (الأذكار ، ص : ۸۰)\nہمارے شیخ حافظ زبیر علی زئی رحمہ اللہ فرماتے ہیں: دو تشہدوں والی نماز کے پہلے تشہد میں بھی درود پڑھنا افضل اور مستحب ہے۔ اگر صرف تشہد پڑھے اور درود نہ پڑھے تو بھی جائز ہے۔\n- تشہد اول میں درود پڑھنے کی افضلیت اور استحباب کی دو دلیلیں ہیں:\nاول: ... عام دلائل (عمومات) سے استدلال، دیکھیے ہفت روزہ الاعتصام لاہور ( ۸ دسمبر ۱۹۸۹ء) میں شائع شدہ مضمون: التحقيق المستحلى فى ثبوت الصلاة على النبي في القعدة الاولى۔ دوم: خاص دلیل، سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ فیدعو ربہ ويـصـلـى على نبيه ثم ينهض ولا يسلم \" پھر آپ اپنے رب کو پکارتے اور اس کے نبی (یعنی اپنے آپ پر درود پڑھتے پھر کھڑے ہو جاتے اور سلام نہ کہتے .. الخ (السنن الکبری للبیہقی: ۵۰۰/۲ وسندہ صحیح، سنن النسائی: ۱۷۲۱)\nتشہد اول میں درود نہ پڑھنے کے جواز والی وہ روایت ہے جس میں آیا ہے کہ سیدنا عبد اللہ بن مسعود رضی اللہ عنہ\nنے تشہد میں التحیات پڑھنے والی حدیث بیان کی پھر اپنے شاگرد سے فرمایا: ”فإذا فعلت هذا فقد قضيت صلاتك، إن شئت أن تقوم فقم وإن شئت أن تقعد فاقعد جب تو نے یہ کر لیا ( التحیات پڑھ لی تو اپنی نماز پوری کر لی ، اگر تو چاہے تو کھڑا ہو جا ( اور باقی نماز پڑھ ) اور اگر چاہے تو بیٹھ جا۔\n(مسند احمد، ج ۱، ص ۴۲۲ ح ۴۰۰۶ وسندہ صحیح)\nسیدنا ابن مسعود رضی اللہ عنہ تشہد میں التحیات پڑھتے پھر جب نماز کے درمیان والا تشہد ہوتا تو تشہد سے فارغ ہو کر کھڑے ہو جاتے تھے .... الخ (مسند احمد، ج ۱۱، ص ۴۵۹، ح ۴۳۸۲ وسنده حسن لذاته ومسحه ابن خزیمہ بروایت : ۷۰۸)۔\nفضائل درود و سلام، ص: (۲۵)،(۲۶)\n(۴) دعا دعا میں بھی نبی صلی اللہ علیہ وسلم پر درود بھیجنا سنت ہے۔\nسیدنا عبد اللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں: ” میں نبی صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہا تھا۔ سیدنا ابو بکر وعمر رضی اللہ عنہما بھی آپ کے ساتھ تھے۔ جب بیٹھا تو میں نے اللہ کی ثنا سے ابتدا کی پھر نبی صلی اللہ علیہ وسلم پر درود پڑھا۔ اس کے بعد میں نے اپنے لیے دعا کی۔ اس پر نبی صلی اللہ علیہ وسلم نے دو مرتبہ فرمایا: ((سل تعطہ، سل تعطہ)) (آپ سوال کیجیے، آپ کو عطا کیا جائے گا، آپ سوال کیجیے، آپ کو عطا کیا جائے گا۔ (سنن الترمذي : ۵۹۳، وسنده حسن) خالد بن سلمہ بیان کرتے ہیں کہ عبد الحمید بن عبد الرحمن نے جب اپنے بیٹے کا ولیمہ کیا تو موسیٰ بن طلحہ سے کہا: ابو عیسی! نبی صلی اللہ علیہ وسلم پر درود پڑھنے کے حوالے سے آپ کے پاس کیا تعلیم پہنچی ہے؟ موسی کہنے لگے: میں نے نبی صلی اللہ علیہ وسلم پر درود کے بارے میں سیدنا زید بن خارجہ رضی اللہ عنہ سے پوچھا تھا۔ انہوں نے کہا تھا کہ میں نے خود رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا کہ آپ پر درود کیسے پڑھا جائے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ((صَلُّوْا وَاجْتَهِدُوا ، ثُمَّ\nقُولُوا : اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مجِيدٌ )) نماز پڑھو اور ( ذکر الہی میں ) خوب کوشش کرو، پھر کہو: اے اللہ! تو محمد صلی اللہ علیہ وسلم پر اور ان کی آل پر برکت نازل فرما، جس طرح آپ نے ابراہیم علیہ السلام پر برکت نازل فرمائی تھی، بلاشبہ آپ نہایت قابل تعریف اور بڑی بزرگی والے ہیں ۔ (سنن النسائی : ۱۲۹۲ ، مسند احمد : ۱۹۹/۱ وسنده صحيح)\nسیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n((أَيْمَا رَجُلٍ مُسْلِمٍ لَمْ يَكُنْ عِنْدَهُ صَدَقَةٌ، فَلْيَقُلْ فِي دُعَائِهِ: اللَّهُمَّ صَلَّ عَلَى مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ، وَصَلِّ عَلَى الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ ، فَإِنَّهَا لَهُ زَكَاةً ))\n\"جس مسلمان شخص کے پاس صدقہ ( کرنے کے لیے مال) نہ ہو، وہ اپنی دعا میں یوں کہے: اے اللہ ! اپنے بندے اور رسول محمد صلی اللہ علیہ وسلم پر رحمت نازل فرما اور مومن مردوں اور مومن عورتوں، مسلمان مردوں اور مسلمان عورتوں پر بھی رحمت نازل فرما۔ یہ الفاظ کہنا اس کے لیے صدقہ بن جائے گا۔ (الأدب المفرد للبخاری : ۶۴۰، وسنده حسن) علامہ نووی رحمہ اللہ (م: ۶۷۶ھ) لکھتے ہیں :\nأجمع العلماء على استحباب ابتداء الدعاء بالحمد لله تعالى والثناء عليه ، ثم الصلاة على رسول اللہ ، وكذلك تختم الدعاء بهما . ”اللہ تعالیٰ کی حمد و ثنا پھر نبی صلی اللہ علیہ وسلم پر درود کے ساتھ دعا کی ابتدا کرنے کے استحباب پر علماء کا اجماع ہے اسی طرح اختتام بھی ان دونوں کے ساتھ کیا جائے ۔“ (الأذكار: ۱۳۱) شیخ الاسلام ابن تیمیہ رحمہ اللہ لکھتے ہیں:\nفإن الصلاة عليه من أعظم الوسائل التي بها يستجاب الدعاء، وقد أمر اللہ بها، والصلاة عليه في الدعاء هو الذي دل عليه الكتاب والسنة والإجماع . ” آپ صلی اللہ علیہ وسلم پر درود بھیجنا دعا کی قبولیت کے بڑے اسباب میں سے ہے اور بلاشبہ اللہ تعالیٰ نے بھی اس کا حکم دیا ہے اور دعا میں آپ صلی اللہ علیہ وسلم پر درود بھیجنا یہ ایسی چیز ہے جس پر کتاب وسنت اور اجماع دلیل ہیں۔\n(مجموع الفتاوى : ۳۴۷/۱)\n(۵) قبر نبوی کے پاس جناب عبد اللہ بن دینار کہتے ہیں: \"رایت عبد اللہ بن عمر يقف على قبر النبي فيصلي على النبي وعلى أبي بكر و عمر میں نے عبداللہ بن عمر رضی اللہ عنہما کو دیکھا وہ نبی صلی اللہ علیہ وسلم کی قبر کے پاس کھڑے ہوتے ، پھر نبی صلی اللہ علیہ وسلم پر اور ابوبکر و عمر پر درود بھیجتے۔“ (المؤطا للامام\nمالك : ۳۹۹ وسنده صحيح)\nامام ابن کثیر رحمہ اللہ (م: ۷۷۱ھ) فرماتے ہیں: \" يستحب الصلاة والسلام عليه عند زيارة قبره\n*\nصلوات اللہ وسلامه علیه ” آپ صلی اللہ علیہ وسلم کی قبر کی زیارت کے وقت آپ پر درود بھیجنا مستحب ہے\n(تفسیر القرآن: ۲۲۴/۵)\nپتا چلا کہ قبر نبوی کے پاس درود پڑھنا مستحب ہے۔ تاہم اس کی فضیلت کے متعلق جو روایتیں بیان کی جاتی ہیں وہ سب غیر ثابت ہیں نیز اس نیت سے درود پڑھنا کہ آپ میرا درود سن رہے ہیں یہ بھی درست اور جائز نہیں۔ صحابہ کرام یا تابعین عظام میں سے کسی سے بھی بسند صحیح یہ ثابت نہیں کہ وہ اس ارادہ ونیت کے ساتھ درود\nپڑھتے تھے۔ (۶) صفا و مروہ پر ... امام نافع فرماتے ہیں کہ سیدنا ابن عمر رضی اللہ عنہما صفا پہاڑی پر چڑھ کر) تین دفعہ اللہ اکبر کہتے پھر فرماتے: \"لا إله إلا اللہ وحده لا شريك له ، له الملك وله الحمد وهو على کل شیء قدیر “ پھر نبی صلی اللہ علیہ وسلم پر درود بھیجتے پھر دعا کرتے ، دعا اور قیام لمبا کرتے۔ پھر مروہ پہاڑی پر بھی اسی طرح کرتے ۔ (فضل الصلاة على النبي صلی اللہ علیہ وسلم : ۸۷ وسنده صحيح) درود کے چند اہم مسائل: مسئلہ ۱: غیر نبی پر درود بھیجنے کے سلسلے میں اہل علم کا اختلاف ہے۔ ہمارے نزدیک راجح یہ ہے کہ\nرسول اللہ صلی اللہ علیہ وسلم کی تبعیت میں غیر نبی پر درود بھیجنے میں کوئی حرج نہیں لیکن مستقلاً جائز نہیں ہے۔\n☆\nسیدنا ابن عباس رضی اللہ عنہما فرماتے ہیں: \"ما أعلم الصلاة تنبغى من أحد على أحد إلا على النبی صلی اللہ علیہ وسلم میرے علم کے مطابق نبی صلی اللہ علیہ وسلم کے علاوہ کسی پر درود بھیجنا جائز نہیں ہے۔“ (المصنف لابن أبي شيبة : ۸۸۰۸\nوسنده صحیح) جعفر بن برقان کہتے ہیں کہ عمر بن عبد العزیز نے خط لکھا: \"أما بعد! فإن أناسا من الناس قد التمسوا الدنيـا بـعـمـل الآخرة وإن الناس من القصاص قد أحدثوا من الصلاة على خلفائهم\n☆\nوأمرائهم عدل صلاتهم على النبي فإذا جاء ك كتابي هذا فمرهم أن تكون صلاتهم على النبيين ودعاؤهم للمسلمين عامة ويدعوا ما سوى ذلك\" اما بعد ! لوگوں میں سے بعض ایسے ہیں جو آخرت کے عمل کے بدلے میں دنیا چاہتے ہیں اور بعض قصہ گو لوگوں نے اپنے خلفاء اور امراء کے لیے نبی صلی اللہ علیہ وسلم پر درود جیسے درود ایجاد کر لیے ہیں لہذا جب تیرے پاس میرا یہ خط پہنچے تو انہیں حکم دو کہ وہ نبیوں پر درود بھیجیں اور عام مسلمانوں کے لیے دعا کریں اس کے علاوہ سب کچھ چھوڑ دیں۔“\n(فضل الصلاة على النبي : ۷۶ وسنده صحيح)\nامام حسین بن مسعود البغوی (م: ۵۱۶ھ) فرماتے ہیں: وكره قوم أن يقال: اللہم صل على فلان إلا على الأنبياء، والنبی صلی اللہ علیہ وسلم کان مخصوصا به ، لأن الصلاة حقه، وله أن يضعها حيث أراد أو يصلى رجل على آل النبي معه علیه السلام اور کچھ لوگوں نے اس بات کو مکروہ جانا ہے کہ یوں کہا جائے: اللہم صل علی فلان (اے اللہ ! فلاں شخص پر درود بھیج ) سوائے انبیاء کرام کے ، وہ (درود) نبی صلی اللہ علیہ وسلم کے ساتھ مخصوص ہے کیونکہ درود آپ کا حق ہے اور آپ کے لیے اجازت ہے کہ اپنے اس حق کو جس پر چاہیں استعمال کریں یا کوئی شخص آپ صلی اللہ علیہ وسلم کے ساتھ آپ کی آل پر درود بھیج سکتا ہے۔\" ایم\nشرح السنة : (۴۶۸/۵)،(۴۸۷)، تحت ح : ۱۵۶۶\nامام یحیی بن شرف النووی (م: ۶۷۶ھ) فرماتے ہیں: اللہم صلى على فلان : فكرهه جمهور أصحابنا ، وهو مذهب ابن عباس ومالك و ابن عيينة وجماعة من السلف، وقال جماعة من العلماء : يجوز ذلك بلا كراهة لهذا الحديث : قال أصحابنا: لا يصلي على غير الأنبياء إلا تبعا لأن الصلاة في لسان السلف مخصوصة بالأنبياء صلاة اللہ وسلامه عليهم كما أن قولنا : عزوجل\" مخصوص باللہ سبحانه و تعالى، فكما لا يقال : محمد عز وجل وإن كان عزيزاً جليلاً، لا يقال : أبو بكر وإن صح المعنى ، واختلف أصحابنا في النهى عن ذلك، هل هو نهى تنزيه أم محرم أو مجرد أدب؟ على ثلاثة أوجه الأصح الأشهر : أنه مكروه كراهة تنزيه، لأنه شعار لأهل البدع وقد نهينا عن شعارهم والمكروه هو ماورد فيه نهى مقصود، واتفقوا على أنه يجوز أن يجعل غير الأنبياء تبعا لهم فى ذلك فيقال: أللهم صل على محمد وعلى آل محمد و أزواجه\n- وذريته وأتباعه لأن السلف لم يمنعوا منه (( اللہم صل علی فلان اسے ہمارے جمہور اصحاب نے مکروہ جانا ہے اور یہ سیدنا ابن عباس، امام مالک، ابن عیینہ اور سلف صالحین کی ایک جماعت کا مذہب ہے۔ اور علماء کی ایک جماعت کا کہنا ہے کہ یہ اس حدیث کی وجہ سے بلا کراہت جائز ہے (لیکن) ہمارے اصحاب کا کہنا ہے کہ غیر انبیاء پر درود نہ بھیجا جائے ، ہوائے تبعیت کے۔ کیونکہ درود سلف کی زبان میں انبیاء کرام علیہم السلام کے ساتھ مخصوص ہے ۔ جیسا کہ ہمارا “عزوجل”“ کہنا اللہ سبحانہ و تعالیٰ کے ساتھ مخصوص ہے۔ چنانچہ محمد عز و جل نہیں کہا جائے گا۔ اگر چہ آپ صلی اللہ علیہ وسلم عزیز و جلیل ہیں۔ ابو بکر صلی اللہ علیہ وسلم نہیں کہا جائے اگر چہ یہ معنی کے اعتبار سے درست ہے۔ ہمارے اصحاب کا اس سلسلے میں وارد نہی کے بارے میں اختلاف ہے کہ کیا وہ نہی تنزیہی ہے یا تحریمی یا خلاف اولیٰ ہے؟ تین اقوال ہیں۔ صحیح اور مشہور ترین یہ ہے کہ یہ مکروہ تنزیہی ہے۔ کیونکہ یہ اہل بدعت کا شعار ہے اور ہمیں ان کے شعار سے منع کیا گیا ہے اور مکر وہ وہ ہے جس میں نہی مقصود وارد ہو اور اس بات پر اتفاق ہے کہ غیر انبیاء پر تبعیت میں جائز ہے، چنانچہ یوں کہا جائے گا: اللہم صل على محمد وعلى آل محمد وازواجه وذريته واتباعه \"اے اے اللہ! محمد صلی اللہ علیہ وسلم پر، آل محمد پر، آپ کی ازواج، اولاد اور آپ کے متبعین پر درود بھیج ) ۔ کیونکہ سلف نے اس سے منع نہیں کیا۔ (شرح صحیح مسلم : ۳۴۶/۱ درسی) مسئلہ ۲: آپ صلی اللہ علیہ وسلم کے اسم گرامی کے ساتھ صلی اللہ علیہ وسلم لکھنے کے بجائے \"ص (\")، صلعم صعم، صلع، صلیو“ وغیرہ جیسے رموز و اشارات لکھنا درست نہیں ہے، بلکہ پورا درود صلی اللہ علیہ وسلم لکھا جائے۔ امام ابن کثیر رحمہ اللہ (م: ۷۷۴ھ) فرماتے ہیں: ابن الصلاح نے کہا: درود و سلام کو مکمل لکھنا چاہیے نہ کہ کم (یا) اشارے میں لکھنا اور صرف ”علیہ السلام پر اکتفا نہیں کرنا چاہیے بلکہ مکمل اور واضح طور پر صلی اللہ علیہ وسلم“ لکھنا\nچاہیے۔ اختصار علوم الحديث ، ص : ۸۷)\nعلامہ سخاوی (م : ۹۰۲ھ ) لکھتے ہیں: ” و اجتنب أيها الكاتب الرمز لها أي للصلاة على رسول اللہ في خطك بأن تقتصر منها على حرفين ونحو ذلك فتكون منقوصة صورة كما يفعله الكسائي والجهلة من ابناء العجم غالبا وعوام الطلبة فيكتبون بد لا عن صلی اللہ علیہ وسلم: 'ص' أو 'صم أو صلم، أو صلعم فذلك لما فيه من نقص الأجر لنقص الكتابة خلاف الاولیٰ“ ”اے لکھنے والے! اپنی لکھائی میں رسول اللہ کا تم پر درود کی اس\nطرح رمز لکھنے سے اجتناب کر کہ دو یا تین چار حرفوں پر اکتفا کر لے۔ اس طرح درود کی صورت ناقص ہو جاتی ہے جیسا کہ کسائی، بہت سے جاہل عجمی اور اکثر طلبہ کا طرز عمل ہے کہ وہ صلی اللہ علیہ وسلم کے بجائے ص، صم، صلم \"\nیا صلم لکھتے ہیں۔ یہ طریقہ کتاب میں نقص کی وجہ سے اجر میں نقص کا باعث ہے۔ خلاف اولیٰ ہے۔\n(فتح المغيث : ۷۱/۳ ، (۷۲)\nمسئلہ ۳: نبی صلی اللہ علیہ وسلم کے علاوہ دیگر انبیاء کرام کے ناموں کے ساتھ صلی اللہ علیہ وسلم کہنا جائز ہے۔ مثلاً یوں کہا جائے کہ عیسیٰ صلی اللہ علیہ وسلم۔\nسیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ایک لمبی حدیث میں آپ صلی اللہ علیہ وسلم نے سیدنا عیسی ابن مریم کے نزول کا ذکر کرتے ہوئے فرمایا: ((فَيَنزِلُ عِيسَى ابْنُ مَرْيَمَ صلی اللہ علیہ وسلم ' پھر عیسی ابن مریم صلی اللہ علیہ (( وسلم اتریں گے۔“ (صحیح مسلم : ۲۸۹۷) سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ایک دوسری روایت میں ہے : ((لَيُوْشِكَنَّ أَنْ يَنْزِلَ فِيْكُمْ ابنُ مَرْيَمَ صلی اللہ علیہ وسلم حَكَمًا مُقْسِطًا يقيناً قریب ہے کہ ابن مریم صلی اللہ علیہ وسلم تم میں اتریں گے، انصاف کرنے والے حاکم ہوں گے.“ (صحیح مسلم : (۱۵۵) سیدنا جابر بن عبد اللہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو یہ فرماتے سنا: (( لا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُوْنَ عَلَى الْحَقِّ ظَاهِرِينَ إِلَى يَوْمِ الْقِيَامَةِ) ” میری امت کا ایک گروہ ہمیشہ حق پر لڑتا رہے گا وہ روز قیامت تک غالب رہیں گے ۔ آپ نے فرمایا: ((فَيَنْزِلُ عِیسَی بْنُ مَريَم صلی اللہ علیہ وسلم. فَيَقُولُ أَمِيرُهُمْ : تَعَالَ صَلَّ لَنَا فَيَقُولُ : لا ، إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ أَمَرَاءُ ، تكرِمَةَ اللَّهِ هذِهِ الأُمَّةَ ”پھر عیسی بن مریم صلی اللہ علیہ وسلم اتریں گے تو ان کا امیر کہے گا: تشریف لائے ہمیں نماز پڑھایے، تو وہ کہیں گے : نہیں، بے شک اللہ کی طرف سے اس امت کو بخشی ہوئی عزت و شرف کی بناء پر تم ہی ایک دوسرے پر امیر ہو۔“ (صحیح مسلم : ۱۵۶)\nسیدنا عبد اللہ بن عمرو رضی اللہ عنہما سے مروی ایک لمبی حدیث میں ہے ( فَيَبْعَثُ اللہ عزوجل عِيسى\nابنَ مَرْيَمَ صلی اللہ علیہ وسلم ..... \"پھر اللہ تعالی عیسی ابن مریم صلی اللہ علیہ وسلم کو بھیجے گا۔ ((\n(مسند احمد : ۱۶۶/۲ وسنده صحيح)\nمسئلہ ۴: درود تاج ، درود لکھی، درود ماهی ، درود تنجینا، درود اکبر ، درود خضریه، درود مقدس، درود شفاعت، درود ناریه، درود خوشیه، درود کوامل، درود عبدوسی، درود هزاره درود خضری، درود رضویه درود خاص درود اول درود قلبی، درود خمسه، درود انعام درود العابدین، درود الاقطاب، درود نور، درود العاشقین، درود طیب، درود کوثر، درود الفاتح، درود حضوری، درود دوامی، درود نورانی، درود قدسی اور درود عالی القدر وغیرہ سب بناوٹی اور من گھڑت درود ہیں۔ کسی بھی حدیث سے ان کا کوئی ثبوت نہیں ملتا اور یہ سب من گھڑت ہیں، ان کے بیان کردہ فضائل بھی خود ساختہ ہیں لہذا ایسے درودوں سے بچنا چاہیے۔ اس طرح الصلاة والسلام علیک یا رسول اللہ والصلاة والسلام علیک یا نور من نور والا درود و سلام بھی خود ساختہ ہے۔"}],[244,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم تعریف کرنے والوں کو دیکھو تو ان کے چہروں پر مٹی ڈالو۔“","",{"t":"کسی کی روبرو تعریف کرنا","k":"صحیح: الکامل لابن عدی: ۳۶۸/۸، ت: ۲۰۰۸۔ ولید بن عباد اور فضل بن صالح ضعیف ہیں، اس میں اور بھی علتیں ہیں، شواہد کی بنا پر حدیث صحیح ہے، دیکھیے: حدیث نمبر ۲۲۸۔"}],[245,"سیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص کسی ایسے مریض کے پاس جائے جس کی موت کا وقت ابھی نہ آیا ہو اور سات مرتبہ یہ دعا پڑھے: أَسْأَلُ اللَّهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيكَ (میں اللہ برتر سے جو عرش عظیم کا رب ہے، سوال کرتا ہوں کہ وہ تجھے شفا دے دے) تو اسے ضرور عافیت مل جاتی ہے۔“","",{"t":"بیمار پرسی کی دعا","k":"صحیح: سنن أبي داؤد، ح: ۳۱۰۶۔ سنن الترمذی، ح: ۲۰۸۳۔ المعجم الکبیر، ح: ۱۲۲۷۲۔ مسند احمد: ۲۳۹/۱۔ صحیح ابن حبان، ح: ۲۹۷۵۔ مسند أبي یعلی، ح: ۲۴۳۰۔","f":"کسی مریض کی عیادت اور بیمار پرسی کرنا عظیم عمل ہے۔ اس پر بڑا اجر ملتا ہے۔\nمریض کے پاس مذکورہ دعا پڑھنا مستحب ہے۔\nیہ دعا موت کے علاوہ ہر مرض کی دوا ہے، اور موت لا علاج ہے۔ بعض اہل علم کا کہنا ہے کہ یہ تغلیباً ہے یعنی اس دعا کے پڑھنے سے اکثر اوقات شفا مل جاتی ہے۔ واللہ اعلم!\nاللہ تعالیٰ کا عرش اس کی تمام مخلوق سے بڑا ہے اور پوری کائنات کو گھیرے ہوئے ہے۔"}],[246,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابراہیم علیہ السلام نے کبھی جھوٹ نہیں بولا سوائے تین (ظاہری) جھوٹوں کے، دو اللہ عزوجل کی ذات کے بارے میں تھے۔ (ایک) ان کا یہ کہنا کہ بے شک میں بیمار ہوں۔ اور (دوسرا) ان کا یہ کہنا کہ بلکہ یہ کام ان کے اس بڑے نے کیا ہے۔“ اور (ایک وہ کہ جب) وہ ایک جابر عیش پرست بادشاہ کے پاس سے گزرے اور ان کی بیوی بھی ان کے ساتھ تھی تو فرمایا: تم (اس بادشاہ سے) کہنا کہ میں اس (ابراہیم) کی بہن ہوں کیونکہ میں اسے کہوں گا کہ وہ میری بہن ہے۔ زمین میں (اس وقت) ہمارے علاوہ کوئی مومن نہیں (اس لحاظ سے تم میری دینی بہن ہو) مجھے ڈر ہے کہ اگر اس نے کہا کہ میری بیوی ہے تو وہ اس پر غلبہ پا لے گا اور ان (ابراہیم کی بیوی) کو بڑا حسن و جمال دیا گیا تھا۔“","",{"t":"ابراہیم علیہ السلام کے تین جھوٹ","k":"صحیح البخاری، ح: ۳۳۵۸۔ صحیح مسلم، ح: ۲۳۷۱۔ سنن أبي داؤد، ح: ۲۲۱۲۔ سنن الترمذی، ح: ۳۱۶۶۔ مسند احمد: ۴۰۳/۲۔","f":"اس حدیث کی شرح و فوائد میں مولانا عبد العزیز علوی رحمہ اللہ لکھتے ہیں: کَذَبَات: کَذْبَة کی جمع ہے، امام ابن انباری کا قول ہے: کذب کی پانچ صورتیں ہیں۔ (۱) نقل کرنے والے نے جو بات سنی ہے، اس کو تبدیل کر دیا اور یہی بات نقل و بیان کر دی، جس کا پتہ نہیں ہے، یہ شکل و قسم انسان کو گناہ گار بناتی ہے اور شرافت کو ختم کر دیتی ہے۔ (۲) چوک جانا، غلطی کرنا، عربوں کے کلام میں کذب کا یہ معنی بہت استعمال ہوا ہے۔ (۳) باطل ہونا، خاک میں مل جانا، کہتے ہیں، کَذَبَ الرَّجُلُ: آدمی کی امید و رجا خاک میں مل گئی، ناکام ہو گئی۔ (۴) کسی کو دھوکہ میں رکھنا۔ (۵) ایسی بات کہنا جو کذب کے مشابہ ہو، لیکن اس سے مقصد صحیح ہو اور کَذَبَ ابراہیم ثَلَاثَ کَذَبَات، والی حدیث میں یہی معنی مراد ہے کہ انہوں نے جھوٹ کے مشابہ بات کہی، جبکہ حقیقتاً تینوں حکم صادق تھے، تاج العروس فصل الکاف من باب الباء، گویا کذب کا لفظ توریہ و تعریض کے لیے استعمال ہوتا ہے۔ إِنِّي سَقِيمٌ: میں بیمار ہوں، انہوں نے جسمانی اور مادی بیماری سمجھی، حالانکہ آپ کا مقصود روحانی بیماری تھا کہ میری روح تمہاری ان شرکیہ حرکتوں کی وجہ سے تڑپ رہی ہے اور میں تمہارے شرک کی بنا پر پریشان ہوں اور یہ بھی ہو سکتا ہے کہ مجھے خطرہ ہے، اگر میں تمہارے ساتھ چلا گیا تو تمہاری شرکیہ حرکتیں دیکھ کر بیمار ہو جاؤں گا۔ بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا: کہ تم ان بتوں کو نفع اور نقصان کا مالک سمجھتے ہو اور بڑے کرنی والے قرار دیتے ہو، میں کہتا ہوں، یہ کام اس بڑے نے کیا، ان سے پوچھو تو سہی، اگر یہ بولتے ہیں، گویا یہ تحکم اور استہزاء کے طور پر کہا ہے، جس طرح ایک بد خط اپنے ایک خوش نویس دوست سے، ایک خوش خط تحریر کے بارے میں پوچھتا ہے: یہ آپ نے لکھی ہے؟ تو وہ جواب دے: نہیں جناب، یہ تو آپ ہی نے لکھی ہے، مقصد یہ ہے، یہ پوچھنے کی کیا ضرورت ہے، یہ میں نے لکھی ہے، یعنی بظاہر جس چیز کی نفی کی ہے، حقیقت میں اس کا اثبات کیا ہے۔ اس حدیث میں حضرت ابراہیم علیہ السلام کی طرف تین کَذَبَات کی نسبت کی گئی، جبکہ قرآن مجید ابراہیم علیہ السلام کو صدیقاً نبیا کا معزز لقب دیتا ہے، اس لیے بعض قدیم و جدید علماء نے اس متفق علیہ یعنی بخاری و مسلم کی روایت کا انکار کیا ہے، حالانکہ یہ کذبات کا لفظ تو توریہ اور تعریض کے لیے استعمال ہوا اور توریہ و تعریض کا استعمال بالکل جائز ہے، جس میں متکلم اپنی بات کا ایک ایسا مفہوم و معنی مراد لیتا ہے، جو صحیح اور درست ہوتا ہے اور سامع اس کا دوسرا معنی لیتا ہے، جس کی رو سے متکلم والا معنی درست نہیں ہوتا، جیسا کہ حضرت ابو طلحہ رضی اللہ عنہ اور حضرت ام سلیم رضی اللہ عنہا کا مشہور واقعہ ہے کہ حضرت ام سلیم نے محسوس کیا، حضرت ابو طلحہ سارے دن کی محنت مشقت کے بعد تھکے ہارے گھر آئیں گے، انہیں ایسی صورت میں ان کے محبوب لخت جگر کی موت کی المناک اطلاع دینا مناسب نہیں ہے، صبح جب آرام سے اٹھیں گے ان کو بتا دوں گی، چنانچہ انہوں نے اپنے لخت جگر کو چارپائی پر لٹا کر اوپر چادر ڈال دی اور گھر کے ایک طرف اس کو رکھ دیا، جب حضرت ابو طلحہ گھر آئے اور آتے ہی پوچھا: بچہ کیسا ہے؟ تو حضرت ام سلیم نے جواب دیا: هَدَأَتْ نَفْسُهُ وَأَرْجُو أَنْ يَكُونَ قَدِ اسْتَرَاحَ، اسے سکون آ گیا ہے اور مجھے امید ہے، اس کی تکلیف کٹ گئی ہے، حضرت ابو طلحہ نے سمجھا بچے کو واقعی آرام آ گیا ہے، اس کی بیماری کٹ گئی ہے، حالانکہ حضرت ام سلیم کا مقصد یہ تھا، بچہ فوت ہو گیا ہے، اس لیے اس کی ہر قسم کی تکلیف اور بیماری ختم ہو گئی ہے تو حضرت ابو طلحہ کے اعتبار سے یہ معنی صحیح نہیں ہے، جبکہ حضرت ام سلیم کے فہم و ذہن کی رو سے یہ معنی درست ہے، اس کو تعریض کہتے ہیں۔ اور اس حدیث سے معلوم ہوا، حضرت ابراہیم نے اپنی پوری زندگی میں، توریہ اور تعریض سے بہت کم کام لیا ہے اور قیامت کے دن اس کو اپنی ایک کمزوری کے طور پر پیش کریں گے تو اس طرح یہ حدیث ان کی عظمت شان پر دلالت کرتی ہے یا ان کی توہین کرتی ہے؟ پہلے ایک غلط معنی لیا گیا اور پھر اس کی آڑ میں ایک صحیح حدیث کا انکار کر دیا گیا۔ حضرت ابراہیم علیہ السلام نے حضرت سارہ کو اپنی بہن قرار دینے کا مشورہ اس لیے دیا کہ بہن تو ہر حال پرایا دھن ہے، اس نے دوسرے گھر سدھارنا ہوتا ہے، لیکن بیوی رفیقہ حیات ہے، اس نے خاوند کے ساتھ رہنا ہوتا ہے، اس لیے اگر وہ کہتی کہ میں ابراہیم کی بیوی ہوں تو وہ راستہ صاف کرنے کے لیے حضرت ابراہیم کو راستہ سے ہٹانے کے لیے قتل کروا دیتا اور حضرت سارہ کے لیے اس کے چنگل سے نکلنے کی کوئی امید نہ رہتی، اس کے برعکس ابراہیم علیہ السلام کے زندہ رہنے کی صورت میں وہ اس کی نجات و خلاصی کے لیے کوئی تدبیر اختیار کرتے، جیسا کہ یہاں فوراً وہ نماز میں کھڑے ہو گئے ہیں اور اللہ تعالیٰ سے دعا کرنے لگے ہیں، اس طرح ان کی زندگی بھی بچ گئی اور دعا کے نتیجہ میں میاں بیوی کی عزت و ناموس بھی بچ گئی، جبکہ ایک خادمہ بھی مل گئی، جب جابر حکمران نے دست درازی کی کوشش کی تو حضرت ابراہیم اور حضرت سارہ کی دعا کے نتیجہ میں اس کا ہاتھ شدت کے ساتھ جکڑ لیا گیا اور اس نے فوراً دعا کی درخواست کی، لیکن اس کی بد عہدی کی بنا پر اس کی پکڑ میں اضافہ ہوتا گیا، حتیٰ کہ گھٹن کی بنا پر وہ ایڑیاں رگڑنے لگا اور حضرت سارہ کو اس کی ہلاکت کا خطرہ پیدا ہو گیا اور وہ ڈر گئیں کہ مجھے قاتلہ قرار دیا جائے گا، اس لیے انہوں نے اس کے حق میں دعا فرمائی اور آخر میں اس سے دعا کی درخواست کے باوجود شیطان یعنی بڑا سرکش جن قرار دیا، کیونکہ لوگ بڑے بڑے کارنامے جنوں کی طرف منسوب کرتے تھے اور ان کی بہت تعظیم و توقیر کرتے تھے۔ اس لیے اس نے ان کو خوش کرنے کے لیے بطور خادمہ اپنی لخت جگر ہاجرہ پیش کی تا کہ حضرت سارہ کا غصہ فرو ہو جائے اور اس کو نقصان نہ پہنچائے۔ (مزید تفصیل کے لیے دیکھیے: خیر الانام، ص: ۲۳۷ تا ۲۴۵)۔ (دیکھیے: تحفة المسلم: ۱۶۱/۷ تا ۱۶۳)"}],[247,"سیدنا عبد اللہ رضی اللہ عنہ تشہد کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں: التحیات للہ والصلوات والطیبات، السلام علیکم ایھا النبی ورحمة اللہ وبرکاتہ السلام علینا وعلی عباد اللہ الصالحین، اشھد ان لا الہ الا اللہ واشھد ان محمد عبدہ ورسولہ (میری تمام قولی، بدنی اور مالی عبادتیں اللہ ہی کے لیے ہیں۔ اے نبی! آپ پر سلام، اللہ کی رحمت اور اس کی برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور اس کے رسول ہیں۔)","",{"t":"تشہد","k":"صحیح البخاری، ح: ۱۲۰۲۔ صحیح مسلم، ح: ۴۰۲۔ سنن أبي داؤد، ح: ۹۶۸۔ سنن الترمذی، ح: ۲۸۹۔ سنن النسائی، ح: ۱۱۶۳۔ سنن ابن ماجہ، ح: ۸۹۹۔","f":"نماز میں تشہد پڑھنا فرض ہے اگر انسان تشہد بھول جائے تو سجدہ سہو لازم آتا ہے۔\nانسان کی تمام قولی، فعلی اور مالی عبادتیں اللہ تعالیٰ ہی کے لیے ہونی چاہئیں۔"}],[248,"سیدنا عبد اللہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں حوض پر تمہارا پیش رو ہوں۔“","",{"t":"نبی صلی اللہ علیہ وسلم کا حوض","k":"صحیح البخاری، ح: ۶۵۷۵۔ صحیح مسلم، ح: ۲۲۸۹۔ مسند أبي یعلی، ح: ۵۱۶۸۔ مسند احمد: ۳۸۴/۱۔","f":"ہمارے نبی صلی اللہ علیہ وسلم کو قیامت کے دن ایک حوض عطا کیا جائے گا جس کا پانی دودھ سے زیادہ سفید اور شہد سے زیادہ میٹھا ہوگا ستاروں کی گنتی کے مطابق آبخورے ہوں گے جسے اس حوض سے ایک گھونٹ پانی مل گیا اسے کبھی پیاس نہیں لگے گی۔ (لمعة الاعتقاد، ص: ۸۴)\nنبی صلی اللہ علیہ وسلم کے اس حوض پر ایمان رکھنا واجب ہے اور اس کا انکار کفر و ضلالت ہے۔\nنبی صلی اللہ علیہ وسلم اپنے حوض پر اپنی امت سے پہلے پہنچے ہوئے ہوں گے۔"}],[249,"قبیصہ کہتے ہیں کہ میں نے سفیان کو یہ فرماتے ہوئے سنا: (قرآن کی) قرأت زہد کے ساتھ ہی صحیح ہوتی ہے اور تو جس چیز کی وجہ سے مردوں پر رشک کرتا ہے اس چیز کی وجہ سے زندوں پر بھی رشک کر اور لوگوں سے ان کے اعمال کے بقدر محبت کر اور طاعت کے وقت عاجزی اختیار کر اور معصیت کے وقت دشواری محسوس کر۔","",{"t":"امام سفیان ثوری کے اقوال زریں","k":"صحیح: الزہد لابن المبارک، ح: ۳۵۴۔ الزہد لہناد، ح: ۵۷۷۔ شعب الایمان، ح: ۱۰۲۹۴۔","f":"امام سفیان کے اس فرمان کا مطلب یہ ہے کہ قرآن مجید کی قرأت اسی صورت میں زیادہ مفید ہو سکتی ہے جب انسان دنیا سے بے رغبت ہو، مردوں پر رشک یہ ہے کہ انسان یہ کہتا ہے کہ جو لوگ دنیا سے جا چکے ہیں وہ اچھے تھے کہ وہ دنیا کے بکھیڑوں سے نجات پا گئے، زندوں پر اس کے ساتھ رشک یہ ہے کہ اللہ نے مجھے دنیا کے بکھیڑوں سے بچایا ہوا ہے۔ لوگوں کے ساتھ ان کے اعمال کے حساب سے محبت کر۔ جو نیک اعمال کریں ان سے محبت کر اور جو برے اعمال کرتے ہیں ان کو دوست مت بنا۔ اللہ تعالیٰ کی اطاعت کرتے وقت بہت زیادہ عاجزی و سکینت اختیار کر اور گناہ کرنا اپنے لیے مشکل بنا لے۔ واللہ اعلم!"}],[250,"سیدنا علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے علی! کیا میں تمہیں ایک ایسا عمل نہ بتاؤں کہ جب تم وہ کرو تو اہل جنت میں سے ہو جاؤ! اور تم اہل جنت میں سے ہو۔“ میں نے کہا: کیوں نہیں (ضرور بتائیں) اے اللہ کے رسول! آپ نے فرمایا: ”بلاشبہ میرے بعد کچھ لوگ ہوں گے وہ ہماری محبت کا دعویٰ کریں گے، دین سے نکلے ہوئے ہوں گے، وہ ہم پر جھوٹ بولیں گے اور ان کی نشانی یہ ہے کہ وہ ابوبکر و عمر کو گالیاں دیں گے۔“","",{"t":"روافض کی نشانی","k":"إسناده ضعيف: رجل من قومه نا معلوم ہے۔ ابو حیان یا ابو جناب کا معاملہ بھی ایسا ہی ہے اگر یہ ابو جناب الکلبي یحیی بن ابی حیہ ہے تو وہ ضعیف ہے۔"}]]);
